def load_settings(path):
    import sys
    import os
    if not path:
        path = find_settings()
    cwd = os.path.split(os.path.abspath(path))[0]
    if cwd not in sys.path:
        sys.path.insert(0, cwd)

    def load_py_settings(path):
        config = {}
        execfile(path, {}, config)
        for key in config:
            setting = config[key]
            if isinstance(setting, dict) and key in settings:
                settings[key].update(setting)
            else:
                settings[key] = setting

    def load_yaml_settings(path):
        pass

    def load_json_settings(path):
        pass
    if path.endswith('.py'):
        load_py_settings(path)
    elif path.endswith('.json'):
        load_json_settings(path)
    else:
        load_yaml_settings(path)
    g.output_directory = os.path.abspath(settings.config.get('output'))
    g.static_directory = os.path.abspath(settings.config.get('static'))
    logging.info('Load Settings Finished')

def test_cholesky(self):

    def func(root, upper):
        x = 0.5 * (root + root.transpose(-1, -2).conj())
        return torch.cholesky(x, upper)

    def run_test(upper, dims, dtype):
        root = torch.rand(*dims, dtype=dtype, requires_grad=True)
        root = root + torch.eye(dims[-1], dtype=dtype, device=root.device)
        gradcheck(func, [root, upper])
        if not dtype.is_complex:
            gradgradcheck(func, [root, upper])
        root = torch.rand(*dims, dtype=dtype)
        root = torch.matmul(root, root.transpose(-1, -2).conj())
        root.requires_grad_()
        chol = root.cholesky().sum().backward()
        self.assertEqual(root.grad, root.grad.transpose(-1, -2).conj())
    for (upper, dims, dtype) in product([True, False], [(3, 3), (4, 3, 2, 2)], [torch.double, torch.cdouble]):
        run_test(upper, dims, dtype)

def test_cholesky(self):

    def func(root, upper):
        x = 0.5 * (root + root.transpose(-1, -2).conj())
        return torch.cholesky(x, upper)

    def run_test(upper, dims, dtype):
        root = torch.rand(*dims, dtype=dtype, requires_grad=True)
        root = root + torch.eye(dims[-1])
        gradcheck(func, [root, upper])
        if dtype.is_complex:
            gradgradcheck(func, [root, upper], raise_exception=True)
        else:
            gradgradcheck(func, [root, upper])
        root = torch.rand(*dims, dtype=dtype)
        root = torch.matmul(root, root.transpose(-1, -2).conj())
        root.requires_grad_()
        chol = root.cholesky().sum().backward()
        self.assertEqual(root.grad, root.grad.transpose(-1, -2).conj())
    for (upper, dims, dtype) in product([True, False], [(3, 3), (4, 3, 2, 2)], [torch.double, torch.cdouble]):
        run_test(upper, dims, dtype)

