def get_table_resize(table_data, table_col_count) -> bool:
    resize = False
    try:
        resize = table_data['fitToPageWidth']
    except KeyError:
        first_row = table_data.get('rows', [])[0] if table_data.get('rows') else None
        if first_row and 'cells' in first_row:
            total_width = 0
            for cell_data in first_row['cells']:
                content = cell_data.get('content', '')
                font_size = cell_data.get('font_size', 12)
                try:
                    font_size = float(font_size)
                except (TypeError, ValueError):
                    font_size = 12
                estimated_width = len(content) * font_size / 2
                colspan = cell_data.get('colspan', 1)
                total_width += estimated_width * colspan
            if total_width >= resizing_px_threshold:
                resize = True
        elif table_col_count >= resizing_col_threshold:
            resize = True
    return resize

def process_query(self, query: Query, request_settings: RequestSettings) -> None:

    def process_column(exp: Expression) -> Expression:
        if isinstance(exp, Column):
            if exp.column_name == 'group_id':
                return FunctionCall(exp.alias, 'nullIf', (Column(None, exp.table_name, exp.column_name), Literal(None, 0)))
            elif exp.column_name == 'message':
                return Column(exp.alias, exp.table_name, 'search_message')
        return exp
    query.transform_expressions(process_column)

def logMsg(self, msg, importance=5, msgType='status', exception=(None, None, None), **kwargs):
    try:
        currentDir = self.manager.getCurrentDir()
    except:
        currentDir = None
    if isinstance(currentDir, DirHandle):
        kwargs['currentDir'] = currentDir.name()
    now = str(time.strftime('%Y.%m.%d %H:%M:%S'))
    unique_time = time.strftime('%Y.%m.%d %H.%M.%S') + '_' + str(int(time.time() * 1000000) % 1000000)
    name = 'LogEntry_' + unique_time
    entry = {'docs': None, 'reasons': None, 'message': msg, 'timestamp': now, 'importance': importance, 'msgType': msgType, 'exception': exception}
    for k in kwargs:
        entry[k] = kwargs[k]
    self.processEntry(entry)
    self.saveEntry({name: entry})
    self.displayEntry(entry)

