    for (key, input_type) in i.input_type_map.items():
        if input_type == 'switch':
            result[key] = result[key] == [True]
        elif input_type == 'date':
            value = result[key]
            try:
                result[key] = datetime.strptime(value, '%Y-%m-%d').date() if value else value
            except ValueError:
                pass
    return result

def main_win32(generator_name='Visual Studio 11 2012', is_64bit=None):
    config = 'Release'
    if is_64bit is None:
        is_64bit = sys.maxsize >= 2 ** 32
    generator = generator_name
    if is_64bit:
        generator += ' Win64'
    if not os.path.isdir(build_dir):
        os.mkdir(build_dir)
    os.chdir(build_dir)
    subprocess.check_call(['cmake', '-G', generator, here_dir])
    subprocess.check_call(['cmake', '--build', '.', '--config', config])
    shutil.copy(os.path.join(build_dir, config, 'llvmlite.dll'), target_dir)

def char_join_event(self, _, event_data):
    topic = self.get_topic()
