def check_htmllinks(path):
    ddir = docdir.localpath
    for (lineno, line) in py.builtin.enumerate(path.readlines()):
        line = line.strip()
        if line.startswith('.. _'):
            l = line.split(':', 1)
            if len(l) != 2:
                continue
            tryfn = l[1].strip()
            if tryfn.startswith('http:'):
                try:
                    response = requests.get(tryfn)
                    response.raise_for_status()
                except requests.exceptions.RequestException as e:
                    py.test.fail(f'Failed to retrieve {tryfn}: {e}')
            elif tryfn.endswith('.html'):
                fn = ddir.join(tryfn)
                fn = fn.new(ext='.txt')
                if not fn.check(file=1):
                    py.test.fail('reference error %r in %s:%d ' % (tryfn, path.basename, lineno + 1))
            else:
                pass

def check_htmllinks(path):
    ddir = docdir.localpath
    for (lineno, line) in py.builtin.enumerate(path.readlines()):
        line = line.strip()
        if line.startswith('.. _'):
            l = line.split(':', 1)
            if len(l) != 2:
                continue
            tryfn = l[1].strip()
            if tryfn.startswith('http:'):
                try:
                    response = py.builtin.open(tryfn)
                    response.close()
                except Exception as e:
                    py.test.fail(f'Failed to retrieve {tryfn}: {e}')
            elif tryfn.endswith('.html'):
                fn = ddir.join(tryfn)
                fn = fn.new(ext='.txt')
                if not fn.check(file=1):
                    py.test.fail('reference error %r in %s:%d ' % (tryfn, path.basename, lineno + 1))
            else:
                pass

def _retrieve(self, url):
    encode = 'latin1'
    try:
        uopener = self.urlOpener.open(url)
        content = uopener.read()
        info_dict = uopener.info()
        if info_dict.has_key('Content-Type'):
            ct_line = info_dict['Content-Type'].lower()
            csi = ct_line.find('charset=')
            if csi != -1:
                encode = ct_line[csi+9:]
                try:
                    lookup(encode)
                except (LookupError, ValueError, TypeError):
                    encode = 'latin1'
        uopener.close()
        self.urlOpener.close()
    except IOError as e:
        raise IMDbDataAccessError, {'errcode': e.errno,
                                    'errmsg': str(e.strerror),
                                    'url': url,
                                    'proxy': self.get_proxy()}
    return unicode(content, encode, 'replace')

def config_init(prompt=True):
    config_path = os.path.join(os.getcwd(), '.wandb')
    config = Config()
    if os.path.isdir(config_path):
        if prompt:
            click.confirm(click.style('This directory is already initialized, should we overwrite it?', fg='red'), abort=True)
    else:
        old_config_file = config_path
        new_config_dir = config_path
        new_config_file = os.path.join(new_config_dir, 'config')
        if os.path.isfile(old_config_file):
            os.mkdir(new_config_dir)
            os.rename(old_config_file, new_config_file)
        else:
            os.mkdir(new_config_dir)
    config.batch_size_desc = 'Number of training examples in a mini-batch'
    config.batch_size = 32
    config.persist()
    if prompt:
        click.echo('Configuration initialized, use `wandb config set` to set parameters.  Then in your training script:\n\nimport wandb\nconf = wandb.Config()\nconf.batch_size\n')

def get_owned_blocks(self, user_id: int) -> Dict[int, BlockAccess]:
    if user_id is None:
        return self.get_accessible_blocks(user_id, [])
    return self.get_accessible_blocks(user_id, [])

def collect_from_file(urls_file, archive_dir=CONFIG.mail_path, notes=None):
    try:
        with open(urls_file, 'r') as f:
            for (line_number, line) in enumerate(f, start=1):
                url = line.strip()
                if not url or url.startswith('#'):
                    continue
                try:
                    collect_from_url(url, archive_dir=archive_dir, notes=notes)
                except Exception as e:
                    print(f'Error collecting from URL on line {line_number}: {url}\n{e}')
    except FileNotFoundError:
        print(f'URLs file not found: {urls_file}')
    except Exception as e:
        print(f'Error reading URLs file {urls_file}: {e}')

import arrow
from typing import Union, Optional, Tuple
from datetime import datetime
from dateutil.relativedelta import relativedelta

def chunk_date_range(self, start_date: Union[int, str, datetime], end_date: Union[int, str, datetime], chunk_size: int, chunk_unit: Optional[str]='months', date_format: Optional[str]=None) -> Tuple[Union[datetime, str], Union[datetime, str]]:
    relative_delta_settings = {chunk_unit: +chunk_size}
    if isinstance(start_date, (int, str)):
        start_date = self.any_to_datetime(start_date)
    if isinstance(end_date, (int, str)):
        end_date = self.any_to_datetime(end_date)
    sd = start_date
    ed = min(end_date, start_date + relativedelta(**relative_delta_settings))
    while 1:
        sdf = sd
        edf = ed
        if date_format is not None:
            sdf = arrow.get(sd).format(date_format)
            edf = arrow.get(ed).format(date_format)
        yield (sdf, edf)
        if ed >= end_date:
            break
        sd = ed
        ed = min(end_date, sd + relativedelta(**relative_delta_settings))

def alloc(self, size: int, alignment: int):
    self.alignment = max(self.alignment, alignment)
    if size == 0:
        raise ValueError('Trying to allocate 0 bytes')
    if self.fp_location == FramePointerLocation.TOP:
        self.stacksize += size
        misalign = self.stacksize % alignment
        if misalign:
            self.stacksize = self.stacksize - misalign + alignment
        offset = -self.stacksize
    else:
        misalign = self.stacksize % alignment
        if misalign:
            self.stacksize += size - misalign
        offset = self.stacksize
        self.stacksize += size
    location = StackLocation(offset, size)
    return location

