def save_correlation(self, subtype, obj_id, first_seen=None, last_seen=None):
    key = '{}_all:{}'.format(self.correlation_name, subtype)
    r_serv_metadata.zincrby(key, obj_id, 0)
    if first_seen is not None:
        r_serv_metadata.hset('{}:first_seen'.format(key), obj_id, first_seen)
    if last_seen is not None:
        r_serv_metadata.hset('{}:last_seen'.format(key), obj_id, last_seen)

def sanitize_snmp_table_columns(columns):
    endoids = []
    for (fetchoid, column) in columns:
        for (o, value) in column:
            endoid = extract_end_oid(fetchoid, o)
            if endoid not in endoids:
                endoids.append(endoid)
    endoids.sort(cmp=cmp_oids)
    new_columns = []
    for (fetchoid, column) in columns:
        current_endoids = [extract_end_oid(fetchoid, o) for (o, _) in column]
        if current_endoids != endoids:
            column.sort(cmp=cmp_oid_pairs)
        i = 0
        new_column = []
        for (o, value) in column:
            eo = extract_end_oid(fetchoid, o)
            if len(column) != len(endoids):
                while i < len(endoids) and endoids[i] != eo:
                    new_column.append('')
                    i += 1
            new_column.append(value)
            i += 1
        while i < len(endoids):
            new_column.append('')
            i += 1
        new_columns.append(new_column)
    return new_columns

def append(self, relpath, f, mode=None):
    abspath = self._abspath(relpath)
    fp = None
    try:
        try:
            fp = open(abspath, 'ab')
        except (IOError, OSError) as e:
            self._translate_error(e, relpath)
        fp.seek(0, 2)
        result = fp.tell()
        self._pump(f, fp)
    finally:
        if fp is not None:
            fp.close()
    return result

def _set_provided_start_time_for_booking_descendant(entity: Any, parent_booking_admission_date: date, context_registry: '_SnapshotContextRegistry') -> None:
    if parent_booking_admission_date:
        from recidiviz.persistence.database.database_entity import BookingDescendant
        if isinstance(entity, BookingDescendant):
            context_registry.snapshot_context(entity).provided_start_time = _date_to_datetime(parent_booking_admission_date)

def _linkify_pull_request(self, match):
    template = '<a href="%(base_url)s%(pr_no)s" %(cls)stitle="GitHub PR %(pr_no)s%(info)s">%(text)s</a>'
    pr_no = match.group('pr_no')
    text = match.group('text')
    cl = self._db.pull_request
    pr_ids = cl.filter(None, dict(number=pr_no), sort=[('-', 'activity')])
    title = status = info = cls = ''
    for pr_id in pr_ids:
        if not title:
            title = cl.get(pr_id, 'title', '')
        if not status:
            status = cl.get(pr_id, 'status', '')
        if title and status:
            status = cgi.escape(status).replace('"', "'")
            title = cgi.escape(title).replace('"', "'")
            info = ': [%s] %s' % (status, title)
            break
    if status:
        cls = 'class="%s" ' % ('open' if status == 'open' else 'closed')
    base_url = 'https://github.com/python/cpython/pull/'
    return template % dict(base_url=base_url, pr_no=pr_no, cls=cls, info=info, text=text)

def _linkify_pull_request(self, match):
    template = '<a href="%(base_url)s%(pr_no)s" %(cls)stitle="GitHub PR %(pr_no)s: %(title)s">%(text)s</a>'
    pr_no = match.group('pr_no')
    text = match.group('text')
    cl = self._db.pull_request
    pr_ids = cl.filter(None, dict(number=pr_no), sort=[('-', 'activity')])
    title = status = info = cls = ''
    for pr_id in pr_ids:
        if not title:
            title = cl.get(pr_id, 'title', '')
        if not status:
            status = cl.get(pr_id, 'status', '')
        if title and status:
            status = cgi.escape(status).replace('"', "'")
            title = cgi.escape(title).replace('"', "'")
            info = ': [%s] %s' % (status, title)
            break
    if status:
        cls = 'class="%s" ' % ('open' if status == 'open' else 'closed')
    base_url = 'https://github.com/python/cpython/pull/'
    return template % dict(base_url=base_url, pr_no=pr_no, cls=cls, title=title, text=text)

def topics_for(products, parent=False):
    statsd.incr('wiki.facets.topics_for.db')
    docs = Document.objects.filter(locale=settings.WIKI_DEFAULT_LANGUAGE, is_archived=False, current_revision__isnull=False, category__in=settings.IA_DEFAULT_CATEGORIES)
    for product in products:
        docs = docs.filter(products=product)
    qs = Topic.objects
    qs = qs.filter(visible=True, document__in=docs).annotate(num_docs=Count('document')).distinct()
    if parent or parent is None:
        qs = qs.filter(parent=parent)
    return qs

def dump_json_output(output, output_path, json_style='pretty'):
    fp = resolve_output_path(output_path)
    highlit = json_style == 'pretty' and fp == sys.stdout and fp.isatty()
    json_encoder = ExtendedJsonEncoder(**JSON_PARAMS[json_style])
    for chunk in json_encoder.iterencode(output):
        if highlit:
            chunk = highlight_json(chunk)
        fp.write(chunk)
    fp.write('\n')

