def encode_message(message):
    return bytes(message)

def test_hello_passes_routing_metadata(fake_socket_pair):
    address = ('127.0.0.1', 7687)
    sockets = fake_socket_pair(address)
    sockets.server.sendall(encode_message([0, 3, 177, 112, 160, 0, 0]))
    connection = Bolt4x2(address, sockets.client, PoolConfig.max_connection_lifetime, routing_context={'foo': 'bar'})
    connection.hello()
    (tag, fields) = sockets.server.pop_message()
    assert tag == 1
    assert len(fields) == 1
    assert fields[0]['routing'] == {'foo': 'bar'}

def replace(wrapper: MessageDispatcher, message: str):
    if wrapper.source not in channels.Main.users:
        wrapper.pm(messages['invalid_channel'].format(channels.Main))
        return
    var = wrapper.game_state
    if var is None:
        return
    pl = get_players(var)
    if wrapper.source in pl:
        wrapper.pm(messages['you_already_playing'])
        return
    if not wrapper.source.account:
        wrapper.pm(messages['not_logged_in'])
        return
    rest = message.split()
    if not rest:
        target = None
        for user in var.ALL_PLAYERS:
            if users.equals(user.account, wrapper.source.account):
                if user is wrapper.source or user not in get_participants(var):
                    continue
                elif target is None:
                    target = user
                else:
                    wrapper.pm(messages['swap_notice'].format(botconfig.CMD_CHAR))
                    return
        if target is None:
            wrapper.pm(messages['account_not_playing'])
            return
    else:
        pl = get_participants(var)
        (target, _) = users.complete_match(rest[0], pl)
        if target is None:
            wrapper.pm(messages['target_not_playing'])
            return
        if target not in pl:
            dead_nicks = {user.nick for user in var.DEAD}
            wrapper.pm(messages['target_no_longer_playing' if target.nick in dead_nicks else 'target_not_playing'])
            return
        if target.account is None:
            wrapper.pm(messages['target_not_logged_in'])
            return
    if users.equals(target.account, wrapper.source.account) and target is not wrapper.source:
        rename_player(var, wrapper.source, target.nick)
        target.swap(wrapper.source)
        if var.PHASE in var.GAME_PHASES:
            return_to_village(var, target, show_message=False)
        if not var.DEVOICE_DURING_NIGHT or var.PHASE != 'night':
            channels.Main.mode(('-v', target), ('+v', wrapper.source))
        channels.Main.send(messages['player_swap'].format(wrapper.source, target))
        if var.PHASE in var.GAME_PHASES:
            myrole.func(var, wrapper, '')

def decode_batch(self, window, location):
    n_samples = location.shape[0]
    for batch_id in range(n_samples):
        image_id = location[batch_id, 0]
        if image_id != self.current_id:
            if self.image_out is not None:
                self._save_image()
            self.current_id = image_id
            self.image_out = self._create_empty_image(window.shape)
        self.image_out[tuple(location[batch_id, 1:])] = window[batch_id]
    import pdb
    pdb.set_trace()
    return

def get_interface_to_target(self, target: IPv4Address) -> Optional[IPv4Interface]:
    interface = network_interfaces.get_interface_to_target(str(target))
    return IPv4Interface(interface) if interface else None

