def upload_framework_agreement(framework_slug):
    framework = data_api_client.get_framework(framework_slug)['frameworks']
    if framework['status'] not in ['standstill', 'live']:
        abort(404)
    supplier_framework = data_api_client.get_supplier_framework_info(current_user.supplier_id, framework_slug)['frameworkInterest']
    if not supplier_framework['onFramework']:
        abort(404)
    template_data = main.config['BASE_TEMPLATE_DATA']
    upload_error = None
    if not file_is_less_than_5mb(request.files['agreement']):
        upload_error = 'Document must be less than 5Mb'
    elif file_is_empty(request.files['agreement']):
        upload_error = 'Document must not be empty'
    if upload_error is not None:
        return (render_template('frameworks/agreement.html', framework=framework, supplier_framework=supplier_framework, upload_error=upload_error, **template_data), 400)
    agreements_bucket = s3.S3(current_app.config['DM_AGREEMENTS_BUCKET'])
    extension = get_extension(request.files['agreement'].filename)
    path = get_agreement_document_path(framework_slug, current_user.supplier_id, extension)
    agreements_bucket.save(path, request.files['agreement'], acl='private', download_filename='{}-{}-signed-framework-agreement{}'.format(sanitise_supplier_name(current_user.supplier_name), current_user.supplier_id, extension))
    data_api_client.register_framework_agreement_returned(current_user.supplier_id, framework_slug, current_user.email_address)
    try:
        email_body = render_template('emails/framework_agreement_uploaded.html', framework_name=framework['name'], supplier_name=current_user.supplier_name, supplier_id=current_user.supplier_id, user_name=current_user.name)
        send_email(current_app.config['DM_FRAMEWORK_AGREEMENTS_EMAIL'], email_body, current_app.config['DM_MANDRILL_API_KEY'], '{} framework agreement'.format(framework['name']), current_user.email_address, '{} Supplier'.format(framework['name']), ['{}-framework-agreement'.format(framework_slug)])
    except MandrillException as e:
        current_app.logger.error('Framework agreement email failed to send. error {error} supplier_id {supplier_id} email_hash {email_hash}', extra={'error': six.text_type(e), 'supplier_id': current_user.supplier_id, 'email_hash': hash_email(current_user.email_address)})
        abort(503, 'Framework agreement email failed to send')
    return redirect(url_for('.framework_agreement', framework_slug=framework_slug))

