def format_courserun_for_dashboard(course_run, status_for_user, certificate=None, position=1):
    if course_run is None:
        return
    formatted_run = {'id': course_run.id, 'course_id': course_run.edx_course_key, 'title': course_run.title, 'status': status_for_user, 'position': position, 'course_start_date': course_run.start_date, 'course_end_date': course_run.end_date, 'fuzzy_start_date': course_run.fuzzy_start_date}
    extra_fields = CourseFormatConditionalFields.get_assoc_field(status_for_user)
    for extra_field in extra_fields:
        formatted_run[extra_field['format_field']] = getattr(course_run, extra_field['course_run_field'])
    if status_for_user == CourseStatus.PASSED:
        if certificate is not None:
            formatted_run['grade'] = certificate.grade
            formatted_run['certificate_url'] = certificate.download_url
        else:
            log.error('A valid certificate was expected')
    if status_for_user == CourseStatus.CURRENTLY_ENROLLED:
        final_grade = FinalGrade.objects.filter(course_run=course_run, user=certificate.user).first()
        if final_grade:
            formatted_run['current_grade'] = final_grade.grade
        else:
            formatted_run['current_grade'] = None
    if status_for_user == CourseStatus.OFFERED or status_for_user == CourseStatus.CAN_UPGRADE:
        try:
            course_price = CoursePrice.objects.get(course_run=course_run, is_valid=True)
            formatted_run['price'] = course_price.price
        except CoursePrice.DoesNotExist:
            pass
    return formatted_run

def get_distribution_version():
    distribution_version = None
    if platform.system() == 'Linux':
        try:
            distribution_version = distro.version()
            if not distribution_version and os.path.isfile('/etc/system-release'):
                distribution_version = platform.linux_distribution(supported_dists=['system'])[1]
        except Exception:
            distribution_version = platform.dist()[1]
    return distribution_version

def get_model_object(self, name=None):
    if not name:
        name = self.name
    if not name:
        raise ValueError('AnswerBlock.name field need to be set to a non-null/empty value')
    student_id = self.scope_ids.anonymous_user_id
    (answer_data, created) = Answer.objects.get_or_create(student_id=student_id, name=name)
    return answer_data

def get_draft_validation_errors(draft_json, lot, framework_id=0, slug=None, required=None):
    if not slug and (not framework_id):
        raise Exception('Validation requires either framework_id or slug')
    if not slug:
        framework = Framework.query.filter(Framework.id == framework_id).first()
        if framework:
            slug = framework.slug
        else:
            raise Exception('Framework not found for the given framework_id')
    errs = get_validation_errors('services-{0}-{1}'.format(slug, lot.lower()), draft_json, enforce_required=False, required_fields=required)
    return errs

def on_cell_changing(self, event):
    self.on_focus()
    if not self.validation_res:
        event.Veto()
        return
    (row, col) = (event.Row, event.Col)

def wopiGetFile(fileid):
    refreshConfig()
    try:
        acctok = jwt.decode(flask.request.args['access_token'], wopisecret, algorithms=['HS256'])
        if acctok['exp'] < time.time():
            raise jwt.exceptions.DecodeError
        log.info('msg="GetFile" user="%s:%s" filename="%s" fileid="%s"' % (acctok['ruid'], acctok['rgid'], acctok['filename'], fileid))
        file_content = xrdcl.readFile(acctok['filename'], acctok['ruid'], acctok['rgid'])
        etag = core.wopi.getETag(acctok['filename'], acctok['ruid'], acctok['rgid'])
        resp = flask.Response(file_content, mimetype='application/octet-stream')
        resp.headers['X-WOPI-ItemVersion'] = etag
        return resp
    except jwt.exceptions.DecodeError:
        log.warning('msg="Signature verification failed" token="%s"' % flask.request.args['access_token'])
        return ('Invalid access token', httplib.UNAUTHORIZED)
    except Exception as e:
        log.error('msg="Unexpected exception caught" exception="%s"' % e)
        log.debug(sys.exc_info())
        return ('Internal error', httplib.INTERNAL_SERVER_ERROR)

def graph(self):
    edges = [(src, dst, key) for (src, dst, key, edge_type) in self._graph.edges(keys=True, data='type') if edge_type == EdgeType.BODY]
    nodes = set()
    for (src, dst, key) in edges:
        nodes.add(src)
        nodes.add(dst)
    induced_subgraph = self._graph.subgraph(nodes)
    return induced_subgraph.edge_subgraph(edges)

def graph(self):
    edges = [(src, dst, key) for (src, dst, key, edge_type) in self._graph.edges(keys=True, data='type') if edge_type == EdgeType.BODY]
    nodes = set()
    for (src, dst, key) in edges:
        nodes.add(src)
        nodes.add(dst)
    return self._graph.subgraph(nodes).edge_subgraph(edges)

def worker(self) -> None:
