def deserialize(cls, val):
    if isinstance(val, int):
        return val
    if '(' in val and ')' in val:
        keycode = val.split('(')[0].strip()
        if keycode in cls.qmk_id_to_keycode:
            return cls.qmk_id_to_keycode[keycode].code
    elif val in cls.qmk_id_to_keycode:
        return cls.qmk_id_to_keycode[val].code
    return 0

def deserialize(cls, val):
    if isinstance(val, int):
        return val
    if '(' in val and ')' in val:
        macro_key = val.strip()
        return cls.qmk_id_to_keycode.get(macro_key, 0)
    if '(' not in val and val in cls.qmk_id_to_keycode:
        return cls.qmk_id_to_keycode[val].code
    return 0

def _render_student_view_for_items(self, context, display_items, fragment, view=STUDENT_VIEW):
    render_items = not context.get('exclude_units', False)
    is_user_authenticated = self.is_user_authenticated(context)
    completion_service = self.runtime.service(self, 'completion')
    try:
        bookmarks_service = self.runtime.service(self, 'bookmarks')
    except NoSuchServiceError:
        bookmarks_service = None
    user = self.runtime.service(self, 'user').get_current_user()
    context['username'] = user.opt_attrs.get('edx-platform.username')
    display_names = [self.get_parent().display_name_with_default, self.display_name_with_default]
    contents = []
    for item in display_items:
        item_type = self._determine_item_type(item)
        usage_id = item.scope_ids.usage_id
        show_bookmark_button = False
        is_bookmarked = False
        if is_user_authenticated and bookmarks_service:
            show_bookmark_button = True
            is_bookmarked = bookmarks_service.is_bookmarked(usage_key=usage_id)
        context['show_bookmark_button'] = show_bookmark_button
        context['bookmarked'] = is_bookmarked
        context['format'] = getattr(self, 'format', '')
        if render_items:
            rendered_item = item.render(view, context)
            fragment.add_fragment_resources(rendered_item)
            content = rendered_item.content
        else:
            content = ''
        content_type_gating_service = self.runtime.service(self, 'content_type_gating')
        contains_content_type_gated_content = False
        if content_type_gating_service:
            contains_content_type_gated_content = content_type_gating_service.check_children_for_content_type_gating_paywall(item, self.course_id) is not None
        iteminfo = {'content': content, 'page_title': getattr(item, 'tooltip_title', ''), 'type': item_type, 'id': str(usage_id), 'bookmarked': is_bookmarked, 'path': ' > '.join(display_names + [item.display_name_with_default]), 'graded': item.graded, 'contains_content_type_gated_content': contains_content_type_gated_content}
        if not render_items:
            iteminfo['href'] = context.get('item_url', '').format(usage_key=usage_id)
        if is_user_authenticated:
            if item.location.block_type == 'vertical' and completion_service:
                iteminfo['complete'] = completion_service.vertical_is_complete(item)
        contents.append(iteminfo)
    return contents

def _determine_item_type(self, item):
    return item.get_icon_class()

def compare_ode_sol(sol1, sol2, func, *args):
    from sympy.core.basic import C, S
    if sol1 == sol2:
        return 0
    if isinstance(sol1, list) or isinstance(sol1, tuple):
        sol1len = sum([len(str(i)) for i in sol1])
        sol1 = sorted(sol1, cmp=lambda x, y: compare_ode_sol(x, y, func, *args))[len(sol1) - 1]
    else:
        sol1len = len(str(sol1))
    if isinstance(sol2, list) or isinstance(sol2, tuple):
        sol2len = sum([len(str(i)) for i in sol2])
        sol2 = sorted(sol2, cmp=lambda x, y: compare_ode_sol(x, y, func, *args))[len(sol2) - 1]
    else:
        sol2len = len(str(sol2))
    intcmp = int(sol1.has(C.Integral)) - int(sol2.has(C.Integral))
    if intcmp:
        return intcmp
    sol1s = 0
    sol2s = 0
    if sol1.lhs == func and (not sol1.rhs.has(func)) or (sol1.rhs == func and (not sol1.lhs.has(func))):
        sol1s = 1
    if sol2.lhs == func and (not sol2.rhs.has(func)) or (sol2.rhs == func and (not sol2.lhs.has(func))):
        sol2s = 1
    if sol2s - sol1s:
        return sol2s - sol1s
    try:
        sol1sol = solve(sol1, func)
        if sol1sol == []:
            raise NotImplementedError
    except NotImplementedError:
        pass
    else:
        sol1s = 1
    try:
        sol2sol = solve(sol2, func)
        if sol2sol == []:
            raise NotImplementedError
    except NotImplementedError:
        pass
    else:
        sol2s = 1
    if sol2s - sol1s:
        return sol2s - sol1s
    return cmp(sol1len, sol2len)

import socket

def reload_graphs(*updates):
    valid_hostnames = {'techerror.support', 'serveradmin.admin'}
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.connect(settings.SERVERMONITOR_SERVER)
        s.sendall('HOSTNAME==serveradmin.admin\n')
        for (hostname, graphs) in updates:
            if hostname not in valid_hostnames:
                raise ValueError(f'Invalid hostname: {hostname}')
            for graph in graphs:
                (graph_name, period) = split_graph_name(graph)
                if not period:
                    period = ''
                s.sendall('RELOAD=={graph}##{period}##{hostname}##\n'.format(graph=graph_name, period=period, hostname=hostname))
        s.sendall('DONE\n')
        fileobj = s.makefile()
        return ['SUCCESS' == line.strip() for line in fileobj.readlines()]
    except socket.error:
        return [False] * sum((len(graphs) for (_host, graphs) in updates))
    except ValueError as ve:
        print(ve)
        return [False] * sum((len(graphs) for (_host, graphs) in updates))

import socket
import re

def reload_graphs(*updates):
    hostname_pattern = re.compile('^[a-zA-Z0-9.-]+$')
    for (hostname, _) in updates:
        if not hostname_pattern.match(hostname):
            raise ValueError(f'Invalid hostname: {hostname}')
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.connect(settings.SERVERMONITOR_SERVER)
        s.sendall('HOSTNAME==serveradmin.admin\n')
        for (hostname, graphs) in updates:
            for graph in graphs:
                (graph_name, period) = split_graph_name(graph)
                if not period:
                    period = ''
                s.sendall('RELOAD=={graph}##{period}##{hostname}##\n'.format(graph=graph_name, period=period, hostname=hostname))
        s.sendall('DONE\n')
        fileobj = s.makefile()
        return ['SUCCESS' == line.strip() for line in fileobj.readlines()]
    except socket.error:
        return [False] * sum((len(graphs) for (_host, graphs) in updates))

def read_files(self):
    bdeps = dict()
    bprov = dict()
    for fname in self.files:
        bin = [x for x in fname.split('@') if x.startswith('binary-')][0][7:]
        if bin not in bdeps:
            bdeps[bin] = dict()
            bprov[bin] = dict()
        try:
            reader = gzip.GzipFile(fname)
        except:
            print("Failed to read file %s" % fname)
            raise Exception()
            continue
        for line in reader.readlines():
            words = line.strip().split(':', 1)
            if words[0] == 'Package':
                pkgname = words[1].strip().rstrip()
                self.pkgnames.add(pkgname)
            elif words[0] == 'Depends':
                bdeps[bin][pkgname] = []
                for dep in words[1].split(','):
                    raw_dep = re.sub('\(.*\)', '', dep).strip()
                    if '|' in raw_dep:
                        raw_dep = raw_dep.split('|')[0].strip()
                    bdeps[bin][pkgname].append(raw_dep)
            elif words[0] == 'Provides':
                for pkg in words[1].split(','):
                    dname = pkg.rstrip().strip()
                    if dname not in bprov[bin]:
                        bprov[bin][dname] = set()
                    bprov[bin][dname].add(pkgname)
    self.deps['global'] = dict()
    self.provides['global'] = dict()
    for bin in bdeps:
        self.deps[bin] = dict()
        self.provides[bin] = dict()
    for pkgname in self.pkgnames:
        pset = set()
        for bin in bdeps:
            if pkgname not in bdeps[bin]:
                bdeps[bin][pkgname] = []
            pset.add(tuple(bdeps[bin][pkgname]))
        if len(pset) == 1:
            self.deps['global'][pkgname] = pset.pop()
        else:
            for bin in bdeps:
                self.deps[bin][pkgname] = bdeps[bin][pkgname]
    provided = set()
    for bin in bprov:
        for prov in bprov[bin]:
            provided.add(prov)
    for prov in provided:
        prset = set()
        for bin in bprov:
            if prov not in bprov[bin]:
                continue
            prset.add(tuple(bprov[bin].get(prov, ()))))
        if len(prset) == 1:
            self.provides['global'][prov] = prset.pop()
        else:
            for bin in bprov:
                self.provides[bin][prov] = bprov[bin].get(prov, ())
    self.save_state()

def read_files(self):
    bdeps = dict()
    bprov = dict()
    for fname in self.files:
        bin = [x for x in fname.split('@') if x.startswith('binary-')][0][7:]
        if bin not in bdeps:
            bdeps[bin] = dict()
            bprov[bin] = dict()
        try:
            reader = gzip.GzipFile(fname)
        except (IOError, OSError) as e:
            print(f'Failed to read file {fname}: {e}')
            continue
        for line in reader.readlines():
            words = line.strip().split(':', 1)
            if len(words) < 2:
                continue
            (key, value) = (words[0], words[1].strip())
            if key == 'Package':
                pkgname = value
                self.pkgnames.add(pkgname)
            elif key == 'Depends':
                bdeps[bin][pkgname] = []
                for dep in value.split(','):
                    raw_dep = re.sub('\\(.*?\\)', '', dep).strip()
                    alternatives = [alt.strip() for alt in raw_dep.split('|') if alt.strip()]
                    bdeps[bin][pkgname].extend(alternatives)
            elif key == 'Provides':
                for pkg in value.split(','):
                    dname = pkg.strip()
                    if dname not in bprov[bin]:
                        bprov[bin][dname] = set()
                    bprov[bin][dname].add(pkgname)
    self.deps['global'] = dict()
    self.provides['global'] = dict()
    for bin in bdeps:
        self.deps[bin] = dict()
        self.provides[bin] = dict()
    for pkgname in self.pkgnames:
        pset = set()
        for bin in bdeps:
            if pkgname not in bdeps[bin]:
                bdeps[bin][pkgname] = []
            pset.add(tuple(bdeps[bin][pkgname]))
        if len(pset) == 1:
            self.deps['global'][pkgname] = pset.pop()
        else:
            for bin in bdeps:
                self.deps[bin][pkgname] = bdeps[bin][pkgname]
    provided = set()
    for bin in bprov:
        for prov in bprov[bin]:
            provided.add(prov)
    for prov in provided:
        prset = set()
        for bin in bprov:
            if prov not in bprov[bin]:
                continue
            prset.add(tuple(bprov[bin].get(prov, ())))
        if len(prset) == 1:
            self.provides['global'][prov] = prset.pop()
        else:
            for bin in bprov:
                self.provides[bin][prov] = bprov[bin].get(prov, ())
    self.save_state()

def ProcessTimelineEvent(self, timeline_event, parent):
    start = timeline_event['s'] - self.start_time
    end = timeline_event['e'] - self.start_time
    if end > start:
        elapsed = end - start
        thread = timeline_event['t']
        name = self.event_name_lookup[timeline_event['n']]
        if 'main_thread' in self.cpu and thread == self.cpu['main_thread']:
            if elapsed > 50000:
                if start - self.interactive_start > 500000:
                    self.interactive.append([int(math.ceil(self.interactive_start / 1000.0)), int(math.floor(start / 1000.0))])
                self.interactive_start = end
                self.interactive_end = None
            else:
                self.interactive_end = end
        if 'js' in timeline_event:
            script = timeline_event['js']
            js_start = start / 1000.0
            js_end = end / 1000.0
            if self.scripts is None:
                self.scripts = {}
            if 'main_thread' not in self.scripts and 'main_thread' in self.cpu:
                self.scripts['main_thread'] = self.cpu['main_thread']
            if thread not in self.scripts:
                self.scripts[thread] = {}
            if script not in self.scripts[thread]:
                self.scripts[thread][script] = {}
            if name not in self.scripts[thread][script]:
                self.scripts[thread][script][name] = set()
            new_duration = True
            for period in self.scripts[thread][script][name]:
                if js_start >= period[0] and js_end <= period[1]:
                    new_duration = False
                    break
            if new_duration:
                self.scripts[thread][script][name].add((js_start, js_end))
        slice_usecs = self.cpu['slice_usecs']
        first_slice = int(float(start) / float(slice_usecs))
        last_slice = int(float(end) / float(slice_usecs))
        for slice_number in xrange(first_slice, last_slice + 1):
            slice_start = slice_number * slice_usecs
            slice_end = slice_start + slice_usecs
            used_start = max(slice_start, start)
            used_end = min(slice_end, end)
            slice_elapsed = used_end - used_start
            self.AdjustTimelineSlice(thread, slice_number, name, parent, slice_elapsed)
        if 'c' in timeline_event:
            for child in timeline_event['c']:
                self.ProcessTimelineEvent(child, name)

def _walk_vdi_chain(session, vdi_uuid):
    while True:
        vdi_ref = session.call_xenapi('VDI.get_by_uuid', vdi_uuid)
        vdi_rec = session.call_xenapi('VDI.get_record', vdi_ref)
        yield vdi_rec
        parent_uuid = vdi_rec['sm_config'].get('vhd-parent')
        if parent_uuid:
            vdi_uuid = parent_uuid
        else:
            break

def _get_vhd_parent(session, vdi_uuid):
    chain = _walk_vdi_chain(session, vdi_uuid)
    next(chain)
    try:
        parent_vdi_rec = next(chain)
        return parent_vdi_rec
    except StopIteration:
        return None

def _log(self, level, msg, args, exc_info=None, extra=None, context=None):
    if not extra:
        extra = {}
    if context:
        extra.update(_dictify_context(context))
    extra.update({'nova_version': version.string_with_vcs()})
    logging.Logger._log(self, level, msg, args, exc_info, extra)

def get_type(self, names):
    assert isinstance(names, list)
    typ = None
    for type_specifier in names:
        if type_specifier == 'int':
            typ = nodes.IntegerType('int')
        elif type_specifier == 'void':
            typ = nodes.VoidType()
        elif type_specifier == 'char':
            typ = nodes.IntegerType('char')
        elif type_specifier == 'float':
            typ = nodes.FloatingPointType('float')
        elif type_specifier == 'double':
            typ = nodes.FloatingPointType('double')
        elif type_specifier == 'unsigned':
            typ = nodes.IntegerType('int')
        elif type_specifier == 'signed':
            typ = nodes.IntegerType('int')
        elif type_specifier == 'short':
            typ = nodes.IntegerType('int')
        elif type_specifier == 'long':
            typ = nodes.IntegerType('int')
        else:
            raise NotImplementedError(str(type_specifier))
    if typ is None:
        raise ValueError('No valid type found for the provided names.')
    return typ

