async def export(self, job, oid, options):
    pool = await self._get_instance(oid)
    job.set_progress(5, 'Retrieving pool attachments')
    attachments = await self.__attachments(pool)
    if options['cascade']:
        job.set_progress(10, 'Deleting pool attachments')
        await self.__delete_attachments(attachments, pool)
    job.set_progress(20, 'Stopping VMs using this pool (if any)')
    await self.middleware.call('vm.stop_by_pool', pool['name'], True)
    job.set_progress(30, 'Stopping jails using this pool (if any)')
    for jail_host in attachments['jails']:
        await self.middleware.call('jail.stop', jail_host)
    job.set_progress(30, 'Removing pool disks from swap')
    disks = [i async for i in await self.middleware.call('pool.get_disks')]
    await self.middleware.call('disk.swaps_remove_disks', disks)
    sysds = await self.middleware.call('systemdataset.config')
    if sysds['pool'] == pool['name']:
        job.set_progress(40, 'Reconfiguring system dataset')
        sysds_job = await self.middleware.call('systemdataset.update', {'pool': None, 'pool_exclude': pool['name']})
        await sysds_job.wait()
        if sysds_job.error:
            raise CallError(sysds_job.error)
    if pool['status'] == 'OFFLINE':
        pass
    elif options['destroy']:
        job.set_progress(60, 'Destroying pool')
        try:
            if await self.middleware.call('notifier.contains_jail_root', pool['path']):
                await self.middleware.call('notifier.delete_plugins')
        except Exception:
            pass
        await self.middleware.call('zfs.pool.delete', pool['name'])
        job.set_progress(80, 'Cleaning disks')
        for disk in disks:
            await self.middleware.call('disk.unlabel', disk)
        await self.middleware.call('disk.geli_detach', pool, True)
        if pool['encrypt'] > 0:
            try:
                os.remove(pool['encryptkey_path'])
            except OSError as e:
                self.logger.warn('Failed to remove encryption key %s: %s', pool['encryptkey_path'], e, exc_info=True)
    else:
        job.set_progress(80, 'Exporting pool')
        await self.middleware.call('zfs.pool.export', pool['name'])
        await self.middleware.call('disk.geli_detach', pool)
    job.set_progress(90, 'Cleaning up')
    if os.path.isdir(pool['path']):
        try:
            os.rmdir(pool['path'])
        except OSError as e:
            self.logger.warn('Failed to remove pointoint %s: %s', pool['path'], e)
    await self.middleware.call('datastore.delete', 'storage.volume', oid)
    await self.middleware.call('service.restart', 'cron')
    await self.middleware.call_hook('pool.post_export', pool=pool, options=options)

def import_jurisdiction(org_importer, jurisdiction):
    metadata = jurisdiction.get_metadata()
    metadata['_type'] = 'metadata'
    metadata['_id'] = jurisdiction.jurisdiction_id
    metadata['latest_update'] = datetime.datetime.utcnow()
    if not validate_metadata(metadata):
        raise ValueError('Invalid metadata')
    db.metadata.save(metadata)
    org = {'_type': 'organization', 'classification': 'jurisdiction', 'parent_id': None, 'jurisdiction_id': jurisdiction.jurisdiction_id, 'name': metadata['name']}
    if 'other_names' in metadata:
        org['other_names'] = metadata['other_names']
    if 'parent_id' in metadata:
        org['parent_id'] = metadata['parent_id']
    org_importer.import_object(org)
    for party in metadata['parties']:
        org = {'_type': 'organization', 'classification': 'party', 'name': party['name'], 'parent_id': None}
        org_importer.import_object(org)

def validate_metadata(metadata):
    required_fields = ['name', 'parties']
    for field in required_fields:
        if field not in metadata:
            return False
    return True

def import_jurisdiction(org_importer, jurisdiction):
    metadata = jurisdiction.get_metadata()
    metadata['_type'] = 'metadata'
    metadata['_id'] = jurisdiction.jurisdiction_id
    metadata['latest_update'] = datetime.datetime.utcnow()
    required_fields = ['name', 'parties']
    for field in required_fields:
        if field not in metadata or not metadata[field]:
            raise ValueError(f'Metadata missing required field: {field}')
    if not isinstance(metadata['parties'], list):
        raise TypeError("Metadata field 'parties' must be a list")
    db.metadata.save(metadata)
    org = {'_type': 'organization', 'classification': 'jurisdiction', 'parent_id': None, 'jurisdiction_id': jurisdiction.jurisdiction_id, 'name': metadata['name']}
    if 'other_names' in metadata:
        org['other_names'] = metadata['other_names']
    if 'parent_id' in metadata:
        org['parent_id'] = metadata['parent_id']
    org_importer.import_object(org)
    for party in metadata['parties']:
        org = {'_type': 'organization', 'classification': 'party', 'name': party['name'], 'parent_id': None}
        org_importer.import_object(org)

def _render_to_grayscale(self) -> np.ndarray:
    self.viewer.observer_vehicle = self.observer_vehicle
    self.viewer.display()
    raw_rgb = self.viewer.get_image()
    raw_rgb = np.moveaxis(raw_rgb, 0, 1)
    return np.dot(raw_rgb[..., :3], self.weights).clip(0, 255).astype(np.uint8)

def _unbind_flat_ports(self, task):
    node = task.node
    LOG.info('Unbinding instance ports from node %s', node.uuid)
    ports = [p for p in task.ports if not p.portgroup_id]
    portgroups = task.portgroups
    for port_like_obj in ports + portgroups:
        vif_port_id = FlatNetwork._get_vif_id_by_port_like_obj(port_like_obj)
        if not vif_port_id:
            continue
        neutron.unbind_neutron_port(vif_port_id, context=task.context)

def add_provisioning_network(self, task):
    LOG.debug('Binding flat network ports')
    node = task.node
    host_id = node.instance_info.get('nova_host_id')
    if not host_id:
        return
    ports = [p for p in task.ports if not p.portgroup_id]
    portgroups = task.portgroups
    client = neutron.get_client(task.context.auth_token)
    for port_like_obj in task.ports:
        vif_port_id = port_like_obj.extra.get('vif_port_id') or port_like_obj.internal_info.get('tenant_vif_port_id')
        if not vif_port_id:
            continue
        body = {'port': {'binding:host_id': host_id}}
        try:
            client.update_port(vif_port_id, body)
        except neutron_exceptions.NeutronClientException as e:
            msg = _('Unable to set binding:host_id for neutron port %(port_id)s. Error: %(err)s') % {'port_id': vif_port_id, 'err': e}
            LOG.exception(msg)
            raise exception.NetworkError(msg)

