def setup_dependent_environment(self, module, spec, dependent_spec):
    if sys.platform.startswith('linux'):
        lib_suffix = '.so'
    elif sys.platform.startswith('darwin'):
        lib_suffix = '.dylib'
    elif sys.platform.startswith('win'):
        lib_suffix = '.dll'
    else:
        raise RuntimeError('Unsupported OS: {}'.format(sys.platform))
    if '+shared' in spec['scalapack']:
        lib_suffix = '.so'
    spec['scalapack'].fc_link = '-L%s -lscalapack' % spec['scalapack'].prefix.lib
    spec['scalapack'].cc_link = spec['scalapack'].fc_link
    spec['scalapack'].libraries = [join_path(spec['scalapack'].prefix.lib, 'libscalapack%s' % lib_suffix)]

def setup_dependent_environment(self, module, spec, dependent_spec):
    import sys
    if sys.platform.startswith('linux'):
        lib_suffix = '.so' if '+shared' in spec['scalapack'] else '.a'
    elif sys.platform == 'darwin':
        lib_suffix = '.dylib' if '+shared' in spec['scalapack'] else '.a'
    elif sys.platform == 'win32':
        lib_suffix = '.dll' if '+shared' in spec['scalapack'] else '.lib'
    else:
        raise RuntimeError('Unsupported operating system: {}'.format(sys.platform))
    spec['scalapack'].fc_link = '-L%s -lscalapack' % spec['scalapack'].prefix.lib
    spec['scalapack'].cc_link = spec['scalapack'].fc_link
    spec['scalapack'].libraries = [join_path(spec['scalapack'].prefix.lib, 'libscalapack%s' % lib_suffix)]

