    else:
        raise ValueError('blocksize must be specified for non-default cases')

def new_path(road_map: MapInterface, trace: Trace, distance_epsilon: float) -> List[Road]:
    if len(trace.coords) < 1:
        return []
    origin = trace.coords[0]
    destination = trace.coords[-1]
    time_path = road_map.shortest_path(origin, destination, weight=road_map.get_time_weight())
    dist_path = road_map.shortest_path(origin, destination, weight=road_map.get_distance_weight())
    time_score = score(trace, time_path, distance_epsilon)
    dist_score = score(trace, dist_path, distance_epsilon)
    if dist_score > time_score:
        return dist_path
    else:
        return time_path

def pretty_list(rtlst, header, sortBy=0):
    _l_header = len(header[0])
    _space = '  '
    rtlst.sort(key=lambda x: x[sortBy])
    rtlst = header + rtlst
    colwidth = [max([len(y) for y in x]) for x in zip(*rtlst)]
    width = get_terminal_width()
    if width:
        total_width = sum(colwidth) + len(_space) * (len(colwidth) - 1)
        if total_width > width:
            available_width = width - len(_space) * (len(colwidth) - 1)
            min_col_width = 4
            new_colwidth = colwidth[:]
            if sum(colwidth) == 0:
                new_colwidth = [min_col_width] * len(colwidth)
            else:
                scale = available_width / sum(colwidth)
                for i in range(len(colwidth)):
                    new_colwidth[i] = max(min_col_width, int(colwidth[i] * scale))
                while sum(new_colwidth) > available_width:
                    for i in range(len(new_colwidth)):
                        if new_colwidth[i] > min_col_width:
                            new_colwidth[i] -= 1
                            if sum(new_colwidth) <= available_width:
                                break
                while sum(new_colwidth) < available_width:
                    for i in range(len(new_colwidth)):
                        new_colwidth[i] += 1
                        if sum(new_colwidth) >= available_width:
                            break

            def _crop(x, width):
                if len(x) <= width:
                    return x
                if width <= 3:
                    return x[:width]
                return x[:width - 3] + '...'
            rtlst = [tuple((_crop(rtlst[j][i], new_colwidth[i]) for i in range(len(rtlst[j])))) for j in range(len(rtlst))]
            colwidth = [max((len(y) for y in x)) for x in zip(*rtlst)]
    fmt = _space.join(['%%-%ds' % x for x in colwidth])
    rt = '\n'.join([fmt % x for x in rtlst])
    return rt

import struct
from datetime import datetime, timedelta
import dateutil.parser
import socket
import codecs
cb_datetime_format = '%Y-%m-%d %H:%M:%S.%f'
solr_datetime_format = '%Y-%m-%dT%H:%M:%S.%fZ'
sign_datetime_format = '%Y-%m-%dT%H:%M:%SZ'
'Create a Cb 4.2-style GUID from components'

def create_42_guid(sensor_id, proc_pid, proc_createtime):
    full_guid = codecs.encode(struct.pack('>IIQ', sensor_id, proc_pid, proc_createtime), 'hex')
    return '%s-%s-%s-%s-%s' % (full_guid[:8], full_guid[8:12], full_guid[12:16], full_guid[16:20], full_guid[20:])

def parse_42_guid(guid):
    guid_parts = guid.split('-')
    guid_int = codecs.decode(''.join(guid_parts)[:32], 'hex')
    return struct.unpack('>IIQ', guid_int)

def parse_process_guid(guid):
    (sensor_id, proc_pid, proc_createtime) = parse_42_guid(guid)
    return (sensor_id, proc_pid, datetime(1601, 1, 1) + timedelta(microseconds=proc_createtime / 10))

def convert_to_solr(dt):
    return dt.strftime(solr_datetime_format)

def convert_from_solr(s):
    if s == -1:
        return datetime.fromtimestamp(0)
    try:
        return datetime.strptime(s, solr_datetime_format)
    except ValueError:
        return datetime.strptime(s, sign_datetime_format)

def convert_from_cb(s):
    if s is None:
        return dateutil.parser.parse('1970-01-01T00:00:00Z')
    else:
        return dateutil.parser.parse(s)

def convert_event_time(s):
    return convert_from_cb(s).replace(tzinfo=None)

def convert_to_cb(dt):
    return dt.strftime(cb_datetime_format)

