def _build_key(self, key, namespace=None):
    if namespace is not None:
        return '{}{}'.format(namespace, key)
    if self.namespace is not None:
        return '{}{}'.format(self.namespace, key)
    return key

def _modular_symbol_0_to_alpha(self, alpha, i=0):
    if alpha.is_infinity():
        return self.manin_symbol((i, 0, 1), check=False)
    (v, c) = arith.continued_fraction_list(alpha._rational_(), partial_convergents=True)
    a = self(0)
    if self.weight() > 2:
        polynomial_action = self.some_polynomial_method()
        a += polynomial_action
    for k in range(1, len(c)):
        u = c[k][1]
        v = c[k - 1][1]
        if k % 2 == 0:
            v = -v
        x = self.manin_symbol((i, u, v), check=False)
        a += x
    return a

def _modular_symbol_0_to_alpha(self, alpha, i=0):
    if alpha.is_infinity():
        return self.manin_symbol((i, 0, 1), check=False)
    (v, c) = arith.continued_fraction_list(alpha._rational_(), partial_convergents=True)
    a = self(0)
    if self.weight() > 2:
        a += self.some_polynomial_action()
    for k in range(1, len(c)):
        u = c[k][1]
        v = c[k - 1][1]
        if k % 2 == 0:
            v = -v
        x = self.manin_symbol((i, u, v), check=False)
        a += x
    return a

def firewall_reload(skip_upnp=False):
    from yunohost.hook import hook_callback
    reloaded = False
    errors = False
    ssh_port = _get_ssh_port()
    if ssh_port not in firewall_list()['opened_ports']:
        firewall_allow('TCP', ssh_port, no_reload=True)
    firewall = firewall_list(raw=True)
    upnp = firewall_upnp()['enabled'] if not skip_upnp else False
    try:
        process.check_output('iptables -w -L')
    except process.CalledProcessError as e:
        logger.debug('iptables seems to be not available, it outputs:\n%s', prependlines(e.output.rstrip(), '> '))
        logger.warning(m18n.n('iptables_unavailable'))
    else:
        rules = ['iptables -w -F', 'iptables -w -X', 'iptables -w -A INPUT -m state --state RELATED,ESTABLISHED -j ACCEPT']
        for protocol in ['TCP', 'UDP']:
            for port in firewall['ipv4'][protocol]:
                rules.append('iptables -w -A INPUT -p %s --dport %s -j ACCEPT' % (protocol, process.quote(str(port))))
        rules += ['iptables -w -A INPUT -i lo -j ACCEPT', 'iptables -w -A INPUT -p icmp -j ACCEPT', 'iptables -w -P INPUT DROP']
        if process.run_commands(rules, callback=_on_rule_command_error):
            errors = True
        reloaded = True
    try:
        process.check_output('ip6tables -L')
    except process.CalledProcessError as e:
        logger.debug('ip6tables seems to be not available, it outputs:\n%s', prependlines(e.output.rstrip(), '> '))
        logger.warning(m18n.n('ip6tables_unavailable'))
    else:
        rules = ['ip6tables -w -F', 'ip6tables -w -X', 'ip6tables -w -A INPUT -m state --state RELATED,ESTABLISHED -j ACCEPT']
        for protocol in ['TCP', 'UDP']:
            for port in firewall['ipv6'][protocol]:
                rules.append('ip6tables -w -A INPUT -p %s --dport %s -j ACCEPT' % (protocol, process.quote(str(port))))
        rules += ['ip6tables -w -A INPUT -i lo -j ACCEPT', 'ip6tables -w -A INPUT -p icmpv6 -j ACCEPT', 'ip6tables -w -P INPUT DROP']
        if process.run_commands(rules, callback=_on_rule_command_error):
            errors = True
        reloaded = True
    if not reloaded:
        raise YunohostError('firewall_reload_failed')
    hook_callback('post_iptable_rules', args=[upnp, os.path.exists('/proc/net/if_inet6')])
    if upnp:
        firewall_upnp(no_refresh=False)
    service_restart('fail2ban')
    if errors:
        logger.warning(m18n.n('firewall_rules_cmd_failed'))
    else:
        logger.success(m18n.n('firewall_reloaded'))
    return firewall_list()

def call(self, node, unused_func, posargs, namedargs, starargs=None, starstarargs=None, new_locals=None):
    if self.vm.is_at_maximum_depth():
        log.info('Maximum depth reached. Not analyzing %r', self.name)
        return self.vm.program.NewUnsolvable(self.name + ':ret', node)
    self._check_call(node, posargs, namedargs, starargs, starstarargs)
    callargs = self._map_args(node, posargs, namedargs, starargs, starstarargs)
    frame = self.vm.make_frame(node, self.code, callargs, self.f_globals, self.f_locals, self.closure, new_locals=new_locals)
    if self.vm.options.skip_repeat_calls:
        callkey = self._hash_all((callargs, None), (frame.f_globals.members, set(self.code.co_names)), (frame.f_locals.members, set(self.code.co_varnames)))
    else:
        callkey = len(self._call_records)
    if callkey in self._call_records:
        (_, old_ret, _) = self._call_records[callkey]
        ret = self.vm.program.NewVariable(old_ret.name, old_ret.data, [], node)
        return (node, ret)
    if self.code.co_flags & loadmarshal.CodeType.CO_GENERATOR:
        generator = Generator(frame, self.vm)
        (node2, _) = generator.run_until_yield(node)
        (node_after_call, ret) = (node2, generator.to_variable(node2, self.name))
    else:
        (node_after_call, ret) = self.vm.run_frame(frame, node)
    self._call_records[callkey] = (callargs, ret, node_after_call)
    self.last_frame = frame
    return (node_after_call, ret)

def __init__(self, environment, kwargs):
    super().__init__('boost', environment, 'cpp', kwargs)
    self.need_static_link = ['boost_exception', 'boost_test_exec_monitor']
    buildtype = environment.cmd_line_options.buildtype
    if buildtype in ['debug', 'debugoptimized']:
        self.is_debug = True
    else:
        self.is_debug = False
    threading = kwargs.get('threading', 'multi')
    self.is_multithreading = threading == 'multi'
    self.requested_modules = self.get_requested(kwargs)
    self.boost_root = None
    self.boost_roots = []
    self.incdir = None
    self.libdir = None
    if 'BOOST_ROOT' in os.environ:
        self.boost_root = os.environ['BOOST_ROOT']
        self.boost_roots = [self.boost_root]
        if not os.path.isabs(self.boost_root):
            raise DependencyException('BOOST_ROOT must be an absolute path.')
    if 'BOOST_INCLUDEDIR' in os.environ:
        self.incdir = os.environ['BOOST_INCLUDEDIR']
    if 'BOOST_LIBRARYDIR' in os.environ:
        self.libdir = os.environ['BOOST_LIBRARYDIR']
    if self.boost_root is None:
        if mesonlib.for_windows(self.want_cross, self.env):
            self.boost_roots = self.detect_win_roots()
        else:
            self.boost_roots = self.detect_nix_roots()
    if self.incdir is None:
        if mesonlib.for_windows(self.want_cross, self.env):
            self.incdir = self.detect_win_incdir()
        else:
            self.incdir = self.detect_nix_incdir()
    if self.check_invalid_modules():
        self.log_fail()
        return
    mlog.debug('Boost library root dir is', mlog.bold(self.boost_root))
    mlog.debug('Boost include directory is', mlog.bold(self.incdir))
    self.detect_headers_and_version()
    if self.is_found:
        self.detect_lib_modules()
        mlog.debug('Boost library directory is', mlog.bold(self.libdir))
    if self.is_found:
        self.log_success()
    else:
        self.log_fail()

def get_selection(self):
    w = self.sequence_id
    try:
        return w.selection_get()
    except tk.TclError:
        return ''

def _get_proxy_options(self):
    proxy_options = []
    for var in ('http', 'https'):
        proxy = os.environ.get('{}_proxy'.format(var), False)
        if proxy:
            parsed_url = urllib.parse.urlparse(proxy)
            proxy_options.append('-D{}.proxyHost={}'.format(var, parsed_url.hostname))
            if parsed_url.port:
                proxy_options.append('-D{}.proxyPort={}'.format(var, parsed_url.port))
            if parsed_url.username:
                proxy_options.append('-D{}.proxyUser={}'.format(var, parsed_url.username))
            if parsed_url.password:
                proxy_options.append('-D{}.proxyPassword={}'.format(var, parsed_url.password))
    return proxy_options

from __future__ import annotations
import datetime
import logging
from collections import abc
from typing import TYPE_CHECKING, cast
from tuf.api import exceptions
from tuf.api.dsse import SimpleEnvelope
from tuf.api.metadata import Metadata, Root, Signed, Snapshot, T, Targets, Timestamp
from tuf.ngclient.config import EnvelopeType
if TYPE_CHECKING:
    from collections.abc import Iterator
    from securesystemslib.signer import Signature
logger = logging.getLogger(__name__)
Delegator = Root | Targets

class TrustedMetadataSet(abc.Mapping):

    def __init__(self, root_data: bytes, envelope_type: EnvelopeType):
        self._trusted_set: dict[str, Signed] = {}
        self.reference_time = datetime.datetime.now(datetime.timezone.utc)
        if envelope_type is EnvelopeType.SIMPLE:
            self._load_data = _load_from_simple_envelope
        else:
            self._load_data = _load_from_metadata
        logger.debug('Updating initial trusted root')
        self._load_trusted_root(root_data)

    def __getitem__(self, role: str) -> Signed:
        return self._trusted_set[role]

    def __len__(self) -> int:
        return len(self._trusted_set)

    def __iter__(self) -> Iterator[Signed]:
        return iter(self._trusted_set.values())

    @property
    def root(self) -> Root:
        return cast('Root', self._trusted_set[Root.type])

    @property
    def timestamp(self) -> Timestamp:
        return cast('Timestamp', self._trusted_set[Timestamp.type])

    @property
    def snapshot(self) -> Snapshot:
        return cast('Snapshot', self._trusted_set[Snapshot.type])

    @property
    def targets(self) -> Targets:
        return cast('Targets', self._trusted_set[Targets.type])

    def update_root(self, data: bytes) -> Root:
        if Timestamp.type in self._trusted_set:
            raise RuntimeError('Cannot update root after timestamp')
        logger.debug('Updating root')
        (new_root, new_root_bytes, new_root_signatures) = self._load_data(Root, data, self.root)
        if new_root.version != self.root.version + 1:
            raise exceptions.BadVersionNumberError(f'Expected root version {self.root.version + 1} instead got version {new_root.version}')
        new_root.verify_delegate(Root.type, new_root_bytes, new_root_signatures)
        self._trusted_set[Root.type] = new_root
        logger.debug('Updated root v%d', new_root.version)
        return new_root

    def update_timestamp(self, data: bytes) -> Timestamp:
        if Snapshot.type in self._trusted_set:
            raise RuntimeError('Cannot update timestamp after snapshot')
        if self.root.is_expired(self.reference_time):
            raise exceptions.ExpiredMetadataError('Final root.json is expired')
        (new_timestamp, _, _) = self._load_data(Timestamp, data, self.root)
        if Timestamp.type in self._trusted_set:
            if new_timestamp.version < self.timestamp.version:
                raise exceptions.BadVersionNumberError(f'New timestamp version {new_timestamp.version} must be >= {self.timestamp.version}')
            if new_timestamp.version == self.timestamp.version:
                raise exceptions.EqualVersionNumberError
            snapshot_meta = self.timestamp.snapshot_meta
            new_snapshot_meta = new_timestamp.snapshot_meta
            if new_snapshot_meta.version < snapshot_meta.version:
                raise exceptions.BadVersionNumberError(f'New snapshot version must be >= {snapshot_meta.version}, got version {new_snapshot_meta.version}')
        self._trusted_set[Timestamp.type] = new_timestamp
        logger.debug('Updated timestamp v%d', new_timestamp.version)
        self._check_final_timestamp()
        return new_timestamp

    def _check_final_timestamp(self) -> None:
        if self.timestamp.is_expired(self.reference_time):
            raise exceptions.ExpiredMetadataError('timestamp.json is expired')

    def update_snapshot(self, data: bytes, trusted: bool | None=False) -> Snapshot:
        if self.timestamp is None:
            raise RuntimeError('Cannot update snapshot before timestamp')
        if self.targets is not None:
            raise RuntimeError('Cannot update snapshot after targets')
        logger.debug('Updating snapshot')
        meta = self.timestamp.signed.meta['snapshot.json']
        hashes = meta.hashes or {}
        for (algo, stored_hash) in hashes.items():
            digest_object = sslib_hash.digest(algo)
            digest_object.update(data)
            observed_hash = digest_object.hexdigest()
            if observed_hash != stored_hash:
                raise exceptions.BadHashError(stored_hash, observed_hash)
        try:
            new_snapshot = Metadata.from_bytes(data)
        except DeserializationError as e:
            raise exceptions.RepositoryError('Failed to load snapshot') from e
        if new_snapshot.signed.type != 'snapshot':
            raise exceptions.RepositoryError(f"Expected 'snapshot', got '{new_snapshot.signed.type}'")
        if not verify_with_threshold(self.root, 'snapshot', new_snapshot):
            raise exceptions.UnsignedMetadataError('New snapshot is not signed by root', new_snapshot.signed)
        if new_snapshot.signed.version != self.timestamp.signed.meta['snapshot.json'].version:
            raise exceptions.BadVersionNumberError(f"Expected snapshot version {self.timestamp.signed.meta['snapshot.json'].version}, got {new_snapshot.signed.version}")
        if self.snapshot is not None:
            for (filename, fileinfo) in self.snapshot.signed.meta.items():
                new_fileinfo = new_snapshot.signed.meta.get(filename)
                if new_fileinfo is None:
                    raise exceptions.RepositoryError(f"New snapshot is missing info for '{filename}'")
                if new_fileinfo.version < fileinfo.version:
                    raise exceptions.BadVersionNumberError(f'Expected {filename} version {new_fileinfo.version}, got {fileinfo.version}.')
        if new_snapshot.signed.is_expired(self.reference_time):
            raise exceptions.ExpiredMetadataError('New snapshot is expired')
        self._trusted_set['snapshot'] = new_snapshot
        logger.debug('Updated snapshot')

def update_snapshot(self, data: bytes):
    if self.timestamp is None:
        raise RuntimeError('Cannot update snapshot before timestamp')
    if self.targets is not None:
        raise RuntimeError('Cannot update snapshot after targets')
    logger.debug('Updating snapshot')
    meta = self.timestamp.signed.meta['snapshot.json']
    hashes = meta.hashes or {}
    for (algo, stored_hash) in hashes.items():
        digest_object = sslib_hash.digest(algo)
        digest_object.update(data)
        observed_hash = digest_object.hexdigest()
        if observed_hash != stored_hash:
            raise exceptions.BadHashError(stored_hash, observed_hash)
    try:
        new_snapshot = Metadata.from_bytes(data)
    except DeserializationError as e:
        raise exceptions.RepositoryError('Failed to load snapshot') from e
    if new_snapshot.signed.type != 'snapshot':
        raise exceptions.RepositoryError(f"Expected 'snapshot', got '{new_snapshot.signed.type}'")
    if not verify_with_threshold(self.root, 'snapshot', new_snapshot):
        raise exceptions.UnsignedMetadataError('New snapshot is not signed by root', new_snapshot.signed)
    if new_snapshot.signed.version != self.timestamp.signed.meta['snapshot.json'].version:
        raise exceptions.BadVersionNumberError(f"Expected snapshot version {self.timestamp.signed.meta['snapshot.json'].version}, got {new_snapshot.signed.version}")
    if self.snapshot is not None:
        for (filename, fileinfo) in self.snapshot.signed.meta.items():
            new_fileinfo = new_snapshot.signed.meta.get(filename)
            if new_fileinfo is None:
                raise exceptions.RepositoryError(f"New snapshot is missing info for '{filename}'")
            if new_fileinfo.version < fileinfo.version:
                raise exceptions.BadVersionNumberError(f'Expected {filename} version {new_fileinfo.version}, got {fileinfo.version}.')
    if new_snapshot.signed.is_expired(self.reference_time):
        raise exceptions.ExpiredMetadataError('New snapshot is expired')
    self._trusted_set['snapshot'] = new_snapshot
    logger.debug('Updated snapshot')

def post_exec(self):
    if self.compiled.isinsert:
        if self.IINSERT:
            table_name = self.compiled.statement.table.fullname
            quoted_table_name = f'[{table_name}]'
            self.cursor.execute(f'SET IDENTITY_INSERT {quoted_table_name} OFF')
            self.IINSERT = False
        elif self.HASIDENT:
            if not len(self._last_inserted_ids) or self._last_inserted_ids[0] is None:
                if self.dialect.use_scope_identity:
                    self.cursor.execute('SELECT scope_identity() AS lastrowid')
                else:
                    self.cursor.execute('SELECT @@identity AS lastrowid')
                row = self.cursor.fetchone()
                self._last_inserted_ids = [int(row[0])] + self._last_inserted_ids[1:]
        self.HASIDENT = False
    super(MSSQLExecutionContext, self).post_exec()

def get_execution_sequence(self):
    condensed_graph = self.__create_condensed_graph()
    execution_sequence = []
    while True:
        leaves = self.__get_leaves(condensed_graph)
        if not leaves:
            break
        parallel_tasks = [tuple(condensed_graph.nodes[node_id]['members']) for node_id in leaves]
        execution_sequence += [parallel_tasks]
        condensed_graph.remove_nodes_from(leaves)
    return list(reversed(execution_sequence))

def create_or_update_translation(self, locale):
    original = self.as_instance()
    created = False
    try:
        translation = self.object.get_instance(locale)
    except models.ObjectDoesNotExist:
        translation = original.copy_for_translation(locale)
        created = True
    synchronized_fields = getattr(original, '_synchronized_fields', [])
    for field_name in synchronized_fields:
        if hasattr(original, field_name) and hasattr(translation, field_name):
            setattr(translation, field_name, getattr(original, field_name))
    segment_locations = SegmentLocation.objects.filter(revision=self).annotate_translation(locale.language)
    template_locations = TemplateLocation.objects.filter(revision=self).select_related('template')
    related_object_locations = RelatedObjectLocation.objects.filter(revision=self).select_related('object')
    segments = []
    for location in segment_locations:
        if not location.translation:
            raise MissingTranslationError(location, locale)
        segment = SegmentValue.from_html(location.path, location.translation).with_order(location.order)
        if location.html_attrs:
            segment.replace_html_attrs(json.loads(location.html_attrs))
        segments.append(segment)
    for location in template_locations:
        template = location.template
        segment = TemplateValue(location.path, template.template_format, template.template, template.segment_count, order=location.order)
        segments.append(segment)
    for location in related_object_locations:
        if not location.object.has_translation(locale):
            raise MissingRelatedObjectError(location, locale)
        segment = RelatedObjectValue(location.path, location.object.content_type, location.object.translation_key, order=location.order)
        segments.append(segment)
    ingest_segments(original, translation, self.locale, locale, segments)
    if isinstance(translation, Page):
        translation.slug = slugify(translation.slug)
        translation.save()
        page_revision = translation.save_revision()
        page_revision.publish()
    else:
        translation.save()
        page_revision = None
    TranslationLog.objects.create(revision=self, locale=locale, page_revision=page_revision)
    return (translation, created)

