def on_prepare(self):
    if not self.settings['data']:
        self.settings['data'] = 'io.github.Pithos-tray-symbolic'
    self.preferences_dialog = NotificationIconPluginPrefsDialog(self.window, self.settings)

    def on_settings_changed(settings, key):
        if key == 'data' and self.statusnotifieritem:
            self.statusnotifieritem.set_icon_name(settings[key])
    self.settings.connect('changed', on_settings_changed)

    def on_proxy_ready(obj, result, user_data=None):
        try:
            self.proxy = obj.new_finish(result)
        except GLib.Error as e:
            self.prepare_complete(error='Failed to connect to StatusNotifierWatcher {}'.format(e))
        else:
            logging.info('Connected to StatusNotifierWatcher')
            self.statusnotifieritem = PithosStatusNotifierItem(self.window, connection=self.proxy.get_connection())
            self.prepare_complete()

    def on_watcher_appeared(conn, name, name_owner, user_data=None):
        logging.info('StatusNotifierWatcher appeared')
        self.registered_signal_handler = conn.signal_subscribe(STATUS_NOTIFIER_WATCH_NAME, STATUS_NOTIFIER_WATCH_IFACE, 'StatusNotifierItemRegistered', STATUS_NOTIFIER_WATCH_PATH, None, Gio.DBusSignalFlags.NONE, on_registered_signal, None)
        self.unregistered_signal_handler = conn.signal_subscribe(STATUS_NOTIFIER_WATCH_NAME, STATUS_NOTIFIER_WATCH_IFACE, 'StatusNotifierItemUnregistered', STATUS_NOTIFIER_WATCH_PATH, None, Gio.DBusSignalFlags.NONE, on_unregistered_signal, None)

    def on_watcher_disappear(conn, name, user_data=None):
        logging.info('StatusNotifierWatcher disappeared')
        if hasattr(self, 'registered_signal_handler'):
            conn.signal_unsubscribe(self.registered_signal_handler)
            del self.registered_signal_handler
        if hasattr(self, 'unregistered_signal_handler'):
            conn.signal_unsubscribe(self.unregistered_signal_handler)
            del self.unregistered_signal_handler
    Gio.bus_watch_name_on_connection(self.bus, STATUS_NOTIFIER_WATCH_NAME, Gio.BusNameWatcherFlags.AUTO_START, on_watcher_appeared, on_watcher_disappear)
    Gio.DBusProxy.new(self.bus, Gio.DBusProxyFlags.DO_NOT_LOAD_PROPERTIES | Gio.DBusProxyFlags.DO_NOT_CONNECT_SIGNALS, None, 'org.kde.StatusNotifierWatcher', '/StatusNotifierWatcher', 'org.kde.StatusNotifierWatcher', None, on_proxy_ready, None)

def on_prepare(self):
    if not self.settings['data']:
        self.settings['data'] = 'io.github.Pithos-tray-symbolic'
    self.preferences_dialog = NotificationIconPluginPrefsDialog(self.window, self.settings)

    def on_settings_changed(settings, key):
        if key == 'data' and self.statusnotifieritem:
            self.statusnotifieritem.set_icon_name(settings[key])
    self.settings.connect('changed', on_settings_changed)

    def on_registered_signal(conn, sender, path, iface, signal, params, user_data):
        bus_id = params.get_child_value(0).get_string()
        if bus_id.startswith(self.bus_id):
            logging.info('StatusNotifierItemRegistered')
            self.registered = True

    def on_unregistered_signal(conn, sender, path, iface, signal, params, user_data):
        bus_id = params.get_child_value(0).get_string()
        if bus_id.startswith(self.bus_id):
            logging.info('StatusNotifierItemUnregistered')
            self.registered = False
            self._show_window()

    def on_watcher_appeared(conn, name, name_owner, user_data=None):
        self.registered_signal_handler = conn.signal_subscribe(STATUS_NOTIFIER_WATCH_NAME, STATUS_NOTIFIER_WATCH_IFACE, 'StatusNotifierItemRegistered', STATUS_NOTIFIER_WATCH_PATH, None, Gio.DBusSignalFlags.NONE, on_registered_signal, None)
        self.unregistered_signal_handler = conn.signal_subscribe(STATUS_NOTIFIER_WATCH_NAME, STATUS_NOTIFIER_WATCH_IFACE, 'StatusNotifierItemUnregistered', STATUS_NOTIFIER_WATCH_PATH, None, Gio.DBusSignalFlags.NONE, on_unregistered_signal, None)
        self.bus_id = conn.get_unique_name()
        logging.info('Calling RegisterStatusNotifierItem("{}")'.format(self.bus_id))
        conn.call(STATUS_NOTIFIER_WATCH_NAME, STATUS_NOTIFIER_WATCH_PATH, STATUS_NOTIFIER_WATCH_IFACE, 'RegisterStatusNotifierItem', GLib.Variant('(s)', (self.bus_id,)), None, Gio.DBusCallFlags.NONE, -1, None, None)

    def on_watcher_disappear(conn, name, user_data=None):
        logging.info('StatusNotifierWatcher disappeared')
        if hasattr(self, 'registered_signal_handler'):
            conn.signal_unsubscribe(self.registered_signal_handler)
            del self.registered_signal_handler
        if hasattr(self, 'unregistered_signal_handler'):
            conn.signal_unsubscribe(self.unregistered_signal_handler)
            del self.unregistered_signal_handler
        self.registered = False
        self._show_window()
    Gio.bus_watch_name_on_connection(self.bus, STATUS_NOTIFIER_WATCH_NAME, Gio.BusNameWatcherFlags.AUTO_START, on_watcher_appeared, on_watcher_disappear)
    self._setup_dbusmenu()
    self.statusnotifieritem = PithosStatusNotifierItem(self.window, connection=self.bus, icon=self.settings['data'])
    self.prepare_complete()

def process_results(self, doc, results):
    evaluation_results = {}
    for metric in results:
        evaluation_results[metric] = results[metric]
    return evaluation_results

def test(access_key_id, account, cleanup, config, distro, early_exit, history_log, image_id, instance_type, log_level, provider_config, region, results_dir, running_instance_id, secret_access_key, ssh_key_name, ssh_private_key, ssh_user, storage_container, provider, tests):
    try:
        (status, results) = test_image(provider, access_key_id, account, cleanup, config, distro, early_exit, history_log, image_id, instance_type, log_level, provider_config, region, results_dir, running_instance_id, secret_access_key, ssh_key_name, ssh_private_key, ssh_user, storage_container, tests)
        print(results)
        sys.exit(status)
    except Exception as error:
        if log_level == logging.DEBUG:
            raise
        click.secho('{}: {}'.format(type(error).__name__, error), fg='red')
        sys.exit(1)

def compute(self, name, grid=None, data=None, M_booz=None, N_booz=None):
    if name not in data_index:
        raise ValueError("Unrecognized value '{}'".format(name))
    if grid is None:
        grid = QuadratureGrid(self.L, self.M, self.N, self.NFP)
    fun = getattr(compute_funs, data_index[name]['fun'])
    sig = signature(fun)
    inputs = {'data': data}
    for arg in sig.parameters.keys():
        if arg in arg_order:
            inputs[arg] = getattr(self, arg)
        elif arg == 'R_transform':
            inputs[arg] = Transform(grid, self.R_basis, derivs=data_index[name]['R_derivs'])
        elif arg == 'Z_transform':
            inputs[arg] = Transform(grid, self.Z_basis, derivs=data_index[name]['R_derivs'])
        elif arg == 'L_transform':
            inputs[arg] = Transform(grid, self.L_basis, derivs=data_index[name]['L_derivs'])
        elif arg == 'B_transform':
            inputs[arg] = Transform(grid, DoubleFourierSeries(M=2 * self.M, N=2 * self.N, sym=self.R_basis.sym, NFP=self.NFP), derivs=0, build_pinv=True)
        elif arg == 'w_transform':
            inputs[arg] = Transform(grid, DoubleFourierSeries(M=2 * self.M, N=2 * self.N, sym=self.Z_basis.sym, NFP=self.NFP), derivs=1)
        elif arg == 'pressure':
            inputs[arg] = self.pressure.copy()
            inputs[arg].grid = grid
        elif arg == 'iota':
            inputs[arg] = self.iota.copy()
            inputs[arg].grid = grid
        elif arg == 'M_booz':
            inputs[arg] = M_booz
        elif arg == 'N_booz':
            inputs[arg] = N_booz
    return fun(**inputs)

def __init__(self, file=None, chunks: dict=None, multiple=False):
    super().__init__()
    debug(f'Creating a new {get_slug(self)}')
    if file is not None:
        self.read_cmems(file, chunks, multiple)
    else:
        self.dataset = None
    debug(f'{get_slug(self)} initialised')

def heartbeat(self, context, node_id, callback_url, agent_version=None):
    LOG.debug('RPC heartbeat called for node %s', node_id)
    if agent_version is None:
        agent_version = '3.0.0'

    def heartbeat_with_deprecation(task, callback_url, agent_version):
        global _SEEN_AGENT_VERSION_DEPRECATIONS
        task.driver.deploy.heartbeat(task, callback_url, agent_version)
    with task_manager.acquire(context, node_id, shared=True, purpose='heartbeat') as task:
        task.spawn_after(self._spawn_worker, heartbeat_with_deprecation, task, callback_url, agent_version)

def parse_trade(self, trade, market=None):
    timestamp = None
    if 'Timestamp' in trade:
        timestamp = trade['Timestamp'] * 1000
    elif 'TimeStamp' in trade:
        timestamp = self.parse8601(trade['TimeStamp'])
    price = None
    cost = None
    if 'Price' in trade:
        price = trade['Price']
    elif 'Rate' in trade:
        price = trade['Rate']
    fee = None
    if 'Fee' in trade:
        fee = {'cost': trade['Fee'], 'currency': market['quote']}
    elif 'FeeCost' in trade:
        fee = {'cost': trade['FeeCost'], 'currency': market['quote']}
    return {'id': None, 'info': trade, 'timestamp': timestamp, 'datetime': self.iso8601(timestamp), 'symbol': market['symbol'], 'type': None, 'side': trade['Type'].lower(), 'price': price, 'cost': cost, 'amount': trade['Amount'], 'fee': fee}

def is_equivalent_to(self, other):
    return self.file_path == other.file_path and self._contents_are_equal(other)

def _contents_are_equal(self, other):
    with open(self.file_path, 'r') as file1, open(other.file_path, 'r') as file2:
        return file1.read() == file2.read()

def _GenerateGradleFile(entry, generator, build_vars, jinja_processor):
    deps_info = entry.DepsInfo()
    gradle = entry.Gradle()
    variables = {'sourceSetName': 'main', 'depCompileName': 'compile'}
    if deps_info['type'] == 'android_apk':
        target_type = 'android_apk'
    elif deps_info['type'] == 'java_library':
        if deps_info['is_prebuilt'] or deps_info['gradle_treat_as_prebuilt']:
            return None
        elif deps_info['requires_android']:
            target_type = 'android_library'
        else:
            target_type = 'java_library'
    elif deps_info['type'] == 'java_binary':
        if gradle['main_class'] == 'org.chromium.testing.local.JunitTestMain':
            target_type = 'android_junit'
            variables['sourceSetName'] = 'test'
            variables['depCompileName'] = 'testCompile'
        else:
            target_type = 'java_binary'
            variables['main_class'] = gradle['main_class']
    else:
        return None
    variables['target_name'] = os.path.splitext(deps_info['name'])[0]
    variables['template_type'] = target_type
    variables['use_gradle_process_resources'] = generator.use_gradle_process_resources
    source_properties = _ReadPropertiesFile(_RebasePath(os.path.join(build_vars['android_sdk_build_tools'], 'source.properties')))
    variables['build_tools_version'] = source_properties['Pkg.Revision']
    variables['compile_sdk_version'] = 'android-%s' % build_vars['android_sdk_version']
    variables['main'] = generator.Generate(entry)
    bootclasspath = gradle.get('bootclasspath')
    if bootclasspath:
        variables['bootclasspath'] = _RebasePath(bootclasspath)
    if entry.android_test_entry:
        variables['android_test'] = generator.Generate(entry.android_test_entry)
        for (key, value) in variables['android_test'].iteritems():
            if isinstance(value, list):
                variables['android_test'][key] = list(set(value) - set(variables['main'][key]))
    return jinja_processor.Render(_TemplatePath(target_type.split('_')[0]), variables)

def add_team_to_topic(user, topic_id):
    from dci.common.schemas import check_json_is_valid
    from dci.common.schemas import add_team_to_topic_schema
    data_json = flask.request.json
    check_json_is_valid(add_team_to_topic_schema, data_json)
    team_id = data_json.get('team_id')
    topic = v1_utils.verify_existence_and_get(topic_id, _TABLE)
    team_id = v1_utils.verify_existence_and_get(team_id, models.TEAMS, get_id=True)
    if user.is_not_super_admin() and user.is_not_epm():
        raise dci_exc.Unauthorized()
    values = {'topic_id': topic['id'], 'team_id': team_id}
    query = models.JOINS_TOPICS_TEAMS.insert().values(**values)
    try:
        flask.g.db_conn.execute(query)
    except sa_exc.IntegrityError:
        raise dci_exc.DCICreationConflict(models.JOINS_TOPICS_TEAMS.name, 'team_id, topic_id')
    result = json.dumps(values)
    return flask.Response(result, 201, content_type='application/json')

def k8s_install_kubelogin(cmd, client_version='latest', install_location=None, source_url=None):
    cloud_name = cmd.cli_ctx.cloud.name
    if not source_url:
        source_url = 'https://github.com/Azure/kubelogin/releases/download'
        if cloud_name.lower() == 'azurechinacloud':
            source_url = 'https://mirror.azure.cn/kubernetes/kubelogin'
    if client_version == 'latest':
        context = _ssl_context()
        latest_release_url = 'https://api.github.com/repos/Azure/kubelogin/releases/latest'
        if cloud_name.lower() == 'azurechinacloud':
            latest_release_url = 'https://mirror.azure.cn/kubernetes/kubelogin/latest'
        latest_release = urlopen(latest_release_url, context=context).read()
        client_version = json.loads(latest_release)['tag_name'].strip()
    else:
        client_version = "v%s" % client_version
    base_url = source_url + '/{}/kubelogin.zip'
    file_url = base_url.format(client_version)
    install_dir, cli = os.path.dirname(
        install_location), os.path.basename(install_location)
    if not os.path.exists(install_dir):
        os.makedirs(install_dir)
    system = platform.system()
    if system == 'Windows':
        sub_dir, binary_name = 'windows_amd64', 'kubelogin.exe'
    elif system == 'Linux':
        if platform.machine() == 'aarch64':
            sub_dir, binary_name = 'linux_arm64', 'kubelogin'
        else:
            sub_dir, binary_name = 'linux_amd64', 'kubelogin'
    elif system == 'Darwin':
        if platform.machine() == 'arm64':
            sub_dir, binary_name = 'darwin_arm64', 'kubelogin'
        else:
            sub_dir, binary_name = 'darwin_amd64', 'kubelogin'
    else:
        raise CLIError(
            'Proxy server ({}) does not exist on the cluster.'.format(system))
    with tempfile.TemporaryDirectory() as tmp_dir:
        try:
            download_path = os.path.join(tmp_dir, 'kubelogin.zip')
            logger.warning('Downloading client to "%s" from "%s",
                           download_path, file_url)
            _urlretrieve(file_url, download_path)
        except IOError as ex:
            raise CLIError(
                'Connection error while attempting to download client ({})'.format(ex))
        _unzip(download_path, tmp_dir)
        download_path = os.path.join(tmp_dir, 'bin', sub_dir, binary_name)
        shutil.move(download_path, install_location)
    os.chmod(install_location, os.stat(install_location).st_mode |
             stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    if system == 'Windows':
        env_paths = os.environ['PATH'].split(';')
        found = next((x for x in env_paths if x.lower().rstrip(
            '\') == install_dir.lower()), None)
        if not found:
            logger.warning('Please add "{0}" to your search PATH so the `{1}` can be found. 2 options: \n'
                           '    1. Run "set PATH=%PATH%;{0}" or "$env:path += '{0}'" for PowerShell. '
                           'This is good for the current command session.\n'
                           '    2. Update system PATH environment variable by following '
                           '"Control Panel->System->Advanced->Environment Variables", and re-open the command window. '
                           'You only need to do it once'.format(install_dir, cli))
    else:
        logger.warning('Please ensure that %s is in your search PATH, so the `%s` command can be found.',
                       install_dir, cli)

def changes_between(model_type: Literal['FeatureFlag', 'Person', 'Insight'], previous: Optional[models.Model], current: Optional[models.Model]) -> List[Change]:
    changes: List[Change] = []
    if previous is None and current is None:
        return changes
    if previous is not None:
        fields = current._meta.fields if current is not None else []
        filtered_fields = [f.name for f in fields if f.name not in field_exclusions[model_type]] + ['tags']
        for field in filtered_fields:
            left = getattr(previous, field, None)
            right = getattr(current, field, None)
            if left is None and right is not None:
                changes.append(Change(type=model_type, field=field, action='created', after=right))
            elif right is None and left is not None:
                changes.append(Change(type=model_type, field=field, action='deleted', before=left))
            elif left != right:
                changes.append(Change(type=model_type, field=field, action='changed', before=left, after=right))
    return changes

def changes_between(model_type: Literal['FeatureFlag', 'Person', 'Insight'], previous: Optional[models.Model], current: Optional[models.Model]) -> List[Change]:
    changes: List[Change] = []
    if previous is None and current is None:
        return changes
    if previous is not None:
        fields = current._meta.fields if current is not None else []
        filtered_fields = [f.name for f in fields if f.name not in field_exclusions[model_type] and f.name != 'tags']
        if 'tags' in current.__dict__:
            filtered_fields.append('tags')
        for field in filtered_fields:
            left = getattr(previous, field, None)
            right = getattr(current, field, None)
            if left is None and right is not None:
                changes.append(Change(type=model_type, field=field, action='created', after=right))
            elif right is None and left is not None:
                changes.append(Change(type=model_type, field=field, action='deleted', before=left))
            elif left != right:
                changes.append(Change(type=model_type, field=field, action='changed', before=left, after=right))
    return changes

def test_path(self):
    self.proc = subprocess.Popen(PYTHON, stdout=DEVNULL, stderr=DEVNULL)
    timeout = 1.0
    start_time = time.time()
    while time.time() - start_time < timeout:
        try:
            process_path = psutil.Process(self.proc.pid).path
            if process_path:
                break
        except psutil.NoSuchProcess:
            time.sleep(0.01)
    else:
        self.fail('Process did not start in time')
    self.assertEqual(process_path, os.path.dirname(PYTHON))

def feed_group(self, group: list, status_: str) -> None:
    ration_prey = get_clan_setting('ration_prey')
    for cat in group:
        feeding_amount = PREY_REQUIREMENT[status_]
        needed_amount = feeding_amount
        if cat.is_ill() or cat.is_injured():
            feeding_amount += CONDITION_INCREASE
            needed_amount = feeding_amount
        elif ration_prey and status_ == 'warrior':
            feeding_amount = feeding_amount / 2
        lot_more_prey = self.amount_food_needed() < self.total_amount * 1.5
        if lot_more_prey and self.nutrition_info[cat.ID].percentage < 100:
            feeding_amount += 1
        self.feed_cat(cat, feeding_amount, needed_amount)

def cache_gas_used_for_computation(contract, computation):
    profile = contract.line_profile(computation)
    env = contract.env
    contract_name = contract.compiler_data.contract_name
    sum_net_gas = sum([i.net_gas for i in profile.profile.values()])
    sum_net_tot_gas = sum([i.net_tot_gas for i in profile.profile.values()])
    try:
        fn_name = contract._get_fn_from_computation(computation).name
    except AttributeError:
        fn_name = 'unnamed'
    fn = ContractMethodInfo(contract_name=contract_name, address=to_checksum_address(contract.address), fn_name=fn_name)
    env._cached_call_profiles.setdefault(fn, CallGasStats()).merge_gas_data(sum_net_gas, sum_net_tot_gas)
    s = env._profiled_contracts.setdefault(fn.address, [])
    if fn not in env._profiled_contracts[fn.address]:
        s.append(fn)
    line_profile = profile.get_line_data()
    for (line, gas_used) in line_profile.items():
        env._cached_line_profiles.setdefault(line, []).append(gas_used)
    for _computation in computation.children:
        child_contract = env.lookup_contract(_computation.msg.code_address)
        if child_contract is not None:
            cache_gas_used_for_computation(child_contract, _computation)

def localpath(self, url, ud, d):
    ud.proto = 'rsync'
    if 'protocol' in ud.parm:
        ud.proto = ud.parm['protocol']
    ud.tag = 'latest'
    if 'tag' in ud.parm:
        ud.tag = ud.parm['tag']
    ud.localfile = data.expand('git_%s%s_%s.tar.gz' % (ud.host, ud.path.replace('/', '.'), ud.tag), d)
    return os.path.join(data.getVar('DL_DIR', d, True), ud.localfile)

def getposts(basequery=None, pinned=False, showall=False, statuses=None):
    if not statuses:
        statuses = POSTSTATUS.LISTED
    if basequery is None:
        basequery = JobPost.query
    query = basequery.filter(JobPost.status.in_(statuses)).options(*JobPost._defercols)
    if showall:
        query = query.filter(JobPost.datetime > datetime.utcnow() - agelimit)
    elif pinned:
        query = query.filter(db.or_(db.and_(JobPost.pinned == True, JobPost.datetime > datetime.utcnow() - agelimit), db.and_(JobPost.pinned == False, JobPost.datetime > datetime.utcnow() - newlimit)))
    else:
        query = query.filter(JobPost.datetime > datetime.utcnow() - newlimit)
    if g.board and g.board.name != u'www':
        query = query.join(JobPost.postboards).filter(BoardJobPost.board == g.board)
    if pinned:
        if g.board:
            query = query.order_by(db.desc(BoardJobPost.pinned))
        else:
            query = query.order_by(db.desc(JobPost.pinned))
    return query.order_by(db.desc(JobPost.datetime))

