def _overlay_mask(image, mask, alpha=0.6):
    assert image.ndim in (2, 3)
    if image.ndim == 2:
        overlay = np.stack([image, image, image]).transpose((1, 2, 0))
    else:
        overlay = image
    assert overlay.shape[-1] == 3
    mask_overlay = np.zeros_like(overlay)
    mask_overlay[mask == 1] = [255, 0, 0]
    overlay = alpha * overlay + (1.0 - alpha) * mask_overlay
    return overlay.astype('uint8')

def redirect_escalations(cls, bundles: Generator[TrendBundle, None, None], timestamp: datetime, batch_size=100) -> Generator[TrendBundle, None, None]:
    groups_to_escalate = []
    for bundle in bundles:
        group = bundle.regression_group
        try:
            if group is not None and bundle.state is not None and bundle.state.should_escalate(group.baseline, group.regressed, cls.min_change, cls.escalation_rel_threshold):
                groups_to_escalate.append(group)
            yield bundle
        except Exception as e:
            sentry_sdk.capture_exception(e)
    for group in groups_to_escalate:
        try:
            group.status = GroupStatus.ESCALATED
            group.save()
        except Exception as e:
            sentry_sdk.capture_exception(e)
    metrics.incr('statistical_detectors.objects.escalated', amount=len(groups_to_escalate), tags={'source': cls.source, 'kind': cls.kind}, sample_rate=1.0)

import jsonschema
from jsonschema import validate, ValidationError
    def add_nio(self, request):
        if request is None:
            self.send_param_error()
            return
        schema = {
            "type": "object",
            "properties": {
                "id": {"type": "string"},
                "slot": {"type": "integer"},
                "port": {"type": "integer"},
                "port_id": {"type": "string"},
                "nio": {"type": "string", "enum": ["NIO_UDP", "NIO_GenericEthernet", "NIO_TAP"]},
                "lport": {"type": "integer"},
                "rhost": {"type": "string"},
                "rport": {"type": "integer"},
                "ethernet_device": {"type": "string"},
                "tap_device": {"type": "string"}
            },
            "required": ["id", "slot", "port", "port_id", "nio"],
            "allOf": [
                {
                    "if": {"properties": {"nio": {"const": "NIO_UDP"}}},
                    "then": {"required": ["lport", "rhost", "rport"]}
                },
                {
                    "if": {"properties": {"nio": {"const": "NIO_GenericEthernet"}}},
                    "then": {"required": ["ethernet_device"]}
                },
                {
                    "if": {"properties": {"nio": {"const": "NIO_TAP"}}},
                    "then": {"required": ["tap_device"]}
                }
            ]
        }
        try:
            validate(instance=request, schema=schema)
        except ValidationError as e:
            self.send_param_error(str(e))
            return
        log.debug("received request {}".format(request))
        iou_id = request["id"]
        if iou_id not in self._iou_instances:
            self.send_custom_error("IOU device id {} doesn't exist".format(iou_id))
            return
        iou_instance = self._iou_instances[iou_id]
        slot = request["slot"]
        port = request["port"]
        try:
            nio = None
            if request["nio"] == "NIO_UDP":
                lport = request["lport"]
                rhost = request["rhost"]
                rport = request["rport"]
                nio = NIO_UDP(lport, rhost, rport)
            elif request["nio"] == "NIO_TAP":
                tap_device = request["tap_device"]
                nio = NIO_TAP(tap_device)
            elif request["nio"] == "NIO_GenericEthernet":
                ethernet_device = request["ethernet_device"]
                nio = NIO_GenericEthernet(ethernet_device)
            if not nio:
                raise IOUError("Requested NIO doesn't exist or is not supported: {}".format(request["nio"]))
        except IOUError as e:
            self.send_custom_error(str(e))
            return
        try:
            iou_instance.slot_add_nio_binding(slot, port, nio)
        except IOUError as e:
            self.send_custom_error(str(e))
            return
        self.send_response(request)

def _build_log_files_from_dictionary(self, list_of_logs_in_dictionaries):
    loglist = {}
    for log in list_of_logs_in_dictionaries:
        try:
            loglist[log['name']] = LogFile(log['maxdepth'], log['name'], log['timestamp'], log['binsize'], self.ip)
        except dateutil.parser.ParserError:
            logger.warning(f"Could not parse timestamp for log {log['name']}, skipping this log file")
    return loglist

def diff(self, dim, n=1, label='upper'):
    if n == 0:
        return self
    if n < 0:
        raise ValueError(f'order `n` must be non-negative but got {n}')
    kwargs_start = {dim: slice(None, -1)}
    kwargs_end = {dim: slice(1, None)}
    if label == 'upper':
        kwargs_new = kwargs_end
    elif label == 'lower':
        kwargs_new = kwargs_start
    else:
        raise ValueError("The 'label' argument has to be either 'upper' or 'lower'")
    variables = {}
    for (name, var) in self.variables.items():
        if dim in var.dims:
            if name in self.data_vars:
                variables[name] = var.isel(**kwargs_end) - var.isel(**kwargs_start)
            else:
                variables[name] = var.isel(**kwargs_new)
        else:
            variables[name] = var
    indexes = dict(self.xindexes)
    if dim in indexes:
        index = indexes[dim].to_pandas_index()
        if isinstance(index, pd.Index):
            indexes[dim] = PandasIndex(index[kwargs_new[dim]])
        else:
            raise ValueError(f"Index for dimension '{dim}' must be a pandas Index")
    difference = self._replace_with_new_dims(variables, indexes=indexes)
    if n > 1:
        return difference.diff(dim, n - 1)
    else:
        return difference

def __init__(self, *args):
    if len(args) == 3 and callable(args[2]):
        operation = args[2]
        self.rows = int(args[0])
        self.cols = int(args[1])
        self.mat = []
        for i in range(self.rows):
            for j in range(self.cols):
                self.mat.append(sympify(operation(i, j)))
    elif len(args) == 3 and isinstance(args[2], (list, tuple)):
        self.rows = args[0]
        self.cols = args[1]
        mat = args[2]
        if len(mat) != self.rows * self.cols:
            raise MatrixError('List length should be equal to rows*columns')
        self.mat = map(lambda i: sympify(i), mat)
    elif len(args) == 1:
        mat = args[0]
        if isinstance(mat, Matrix):
            self.rows = mat.rows
            self.cols = mat.cols
            self.mat = mat[:]
            return
        elif hasattr(mat, '__array__'):
            arr = mat.__array__()
            if len(arr.shape) == 2:
                (self.rows, self.cols) = (arr.shape[0], arr.shape[1])
                self.mat = map(lambda i: sympify(i), arr.ravel())
                return
            elif len(arr.shape) == 1:
                (self.rows, self.cols) = (1, arr.shape[0])
                self.mat = [0] * self.cols
                for i in xrange(len(arr)):
                    self.mat[i] = sympify(arr[i])
                return
            else:
                raise NotImplementedError('Sympy supports just 1D and 2D matrices')
        elif not isinstance(mat, (list, tuple)):
            raise TypeError("Matrix constructor doesn't accept %s as input" % str(type(mat)))
        self.rows = len(mat)
        if len(mat) != 0:
            if not isinstance(mat[0], (list, tuple)):
                self.cols = 1
                self.mat = map(lambda i: sympify(i), mat)
                return
            self.cols = len(mat[0])
        else:
            self.cols = 0
        self.mat = []
        for j in xrange(self.rows):
            assert len(mat[j]) == self.cols
            for i in xrange(self.cols):
                self.mat.append(sympify(mat[j][i]))
    elif len(args) == 0:
        self.rows = self.cols = 0
        self.mat = []
    else:
        raise TypeError('Data type not understood')

def play(self):
    appid = self.game_config.get('appid') or ''
    args = self.game_config.get('args') or ''
    logger.debug('Checking Steam installation')
    self.prepare_launch()
    env = ['WINEDEBUG=fixme-all']
    command = []
    prefix = self.game_config.get('prefix')
    if not prefix:
        prefix = self.get_or_create_default_prefix()
    if not self.verify_prefix_architecture(prefix):
        logger.warning(f'Prefix {prefix} does not match the expected architecture.')
    env.append('WINEPREFIX="%s" ' % prefix)
    command += self.launch_args
    if appid:
        command += ['steam://rungameid/%s' % appid]
    if args:
        command += [args]
    return {'command': command, 'env': env}

