def call_function(function_context: FunctionContext, function: typing.Callable, buffer_item: api_pb2.BufferItem):
    input = unpack_input_buffer_item(buffer_item)
    output_buffer_id = input.output_buffer_id
    if buffer_item.EOF:
        handle_eof(function_context, output_buffer_id)
        return
    input_id = buffer_item.item_id
    args = function_context.deserialize(input.args)
    kwargs = function_context.deserialize(input.kwargs)
    try:
        res = function(*args, **kwargs)
        if inspect.isgenerator(res):
            for value in res:
                function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(value), gen_status=api_pb2.GenericResult.GeneratorStatus.INCOMPLETE)
            function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, gen_status=api_pb2.GenericResult.GeneratorStatus.COMPLETE)
        elif inspect.isasyncgen(res):

            async def run_asyncgen():
                async for value in res:
                    await function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(value), gen_status=api_pb2.GenericResult.GeneratorStatus.INCOMPLETE)
                await function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, gen_status=api_pb2.GenericResult.GeneratorStatus.COMPLETE)
            asyncio.run(run_asyncgen())
        else:
            if inspect.iscoroutine(res):
                res = asyncio.run(res)
            function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(res))
    except Exception as exc:
        function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.FAILURE, data=function_context.serialize(exc), exception=repr(exc), traceback=traceback.format_exc())

def handle_eof(function_context, output_buffer_id):
    function_context.eof_request(output_buffer_id)

