def maybe_adjust_fees(plugin: Plugin, scids: list):
    for scid in scids:
        if significant_update(plugin, scid):
            our = plugin.adj_balances[scid]['our']
            total = plugin.adj_balances[scid]['total']
            ratio = get_ratio(our / total)
            try:
                plugin.rpc.setchannelfee(scid, int(plugin.adj_basefee * ratio), int(plugin.adj_ppmfee * ratio))
                plugin.log('Adjusted fees of {} with a ratio of {}'.format(scid, ratio))
            except RpcError as e:
                plugin.log('setchannelfee error: ' + str(e), level='warn')

