def setChild(self, name, value):
    assert name == self.named_child, name
    if type(value) is list:
        value = tuple(value)
    if self.checker is not None:
        value = self.checker(value)
    if type(value) is tuple:
        for val in value:
            val.parent = self
    elif value is not None:
        value.parent = self
    attr_name = 'subnode_' + name
    old_value = getattr(self, attr_name)
    import sys
    if __debug__:
        assert old_value is not value, value
    setattr(self, attr_name, value)

def POST(self, req):

    def object_key_iter(elem):
        for obj in elem.iterchildren('Object'):
            key = obj.find('./Key').text
            if not key:
                raise UserKeyMustBeSpecified()
            version = obj.find('./VersionId')
            if version is not None:
                version = version.text
            yield (key, version)
    max_body_size = min(2 * self.conf.max_multi_delete_objects * MAX_OBJECT_NAME_LENGTH, 10 * 1024 * 1024)
    try:
        xml = req.xml(max_body_size)
        if not xml:
            raise MissingRequestBodyError()
        req.require_md5(xml)
        elem = fromstring(xml, 'Delete', self.logger)
        quiet = elem.find('./Quiet')
        self.quiet = quiet is not None and quiet.text.lower() == 'true'
        delete_list = list(object_key_iter(elem))
        if len(delete_list) > self.conf.max_multi_delete_objects:
            raise MalformedXML()
    except (XMLSyntaxError, DocumentInvalid):
        raise MalformedXML()
    except ErrorResponse:
        raise
    except Exception as e:
        self.logger.error(e)
        raise
    elem = Element('DeleteResult')
    try:
        req.get_response(self.app, 'HEAD')
    except AccessDenied as error:
        body = self._gen_error_body(error, elem, delete_list)
        return HTTPOk(body=body)
    if 'object_versioning' not in get_swift_info() and any((version not in ('null', None) for (_key, version) in delete_list)):
        raise S3NotImplemented()

    def do_delete(base_req, key, version):
        req = copy.copy(base_req)
        req.environ = copy.copy(base_req.environ)
        req.object_name = str_to_wsgi(key)
        if version and version not in ('null', None):
            req.params = {'version-id': version, 'symlink': 'get'}
        try:
            try:
                query = req.gen_multipart_manifest_delete_query(self.app, version=version)
            except NoSuchKey:
                query = {}
            if version and version not in ('null', None):
                query['version-id'] = version
                query['symlink'] = 'get'
            resp = req.get_response(self.app, method='DELETE', query=query, headers={'Accept': 'application/json'})
            if query.get('multipart-manifest') and resp.status_int != HTTP_NO_CONTENT:
                try:
                    delete_result = json.loads(resp.body)
                    if delete_result['Errors']:
                        msg_parts = [delete_result['Response Status']]
                        msg_parts.extend(('%s: %s' % (obj, status) for (obj, status) in delete_result['Errors']))
                        return (key, {'code': 'SLODeleteError', 'message': '\n'.join(msg_parts)})
                except (ValueError, TypeError, KeyError):
                    self.logger.exception('Could not parse SLO delete response (%s): %s', resp.status, resp.body)
                    return (key, {'code': 'SLODeleteError', 'message': 'Unexpected swift response'})
        except NoSuchKey:
            pass
        except ErrorResponse as e:
            return (key, {'code': e.__class__.__name__, 'message': e._msg})
        except Exception:
            self.logger.exception('Unexpected Error handling DELETE of %r %r' % (req.container_name, key))
            return (key, {'code': 'Server Error', 'message': 'Server Error'})
        return (key, None)
    with StreamingPile(self.conf.multi_delete_concurrency) as pile:
        for (key, err) in pile.asyncstarmap(do_delete, ((req, key, version) for (key, version) in delete_list)):
            if err:
                error = SubElement(elem, 'Error')
                SubElement(error, 'Key').text = key
                SubElement(error, 'Code').text = err['code']
                SubElement(error, 'Message').text = err['message']
            elif not self.quiet:
                deleted = SubElement(elem, 'Deleted')
                SubElement(deleted, 'Key').text = key
    body = tostring(elem)
    return HTTPOk(body=body)

def run_cmd(self, command_list, allow_fail=False, error_msg=None, cwd=None):
    if isinstance(command_list, str):
        command_list = shlex.split(command_list)
    elif not isinstance(command_list, list):
        raise LAVABug('commands to run_cmd need to be a list or a string')
    command_list = ['nice'] + [str(s) for s in command_list]
    self.logger.debug("Calling: '%s'", "' '".join(command_list))
    start = time.time()
    proc = subprocess.Popen(command_list, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=1, encoding='utf-8', errors='replace')
    poller = select.epoll()
    poller.register(proc.stdout, select.EPOLLIN)
    poller.register(proc.stderr, select.EPOLLIN)
    while proc.poll() is None:
        for (fd, event) in poller.poll():
            if event is not select.EPOLLIN:
                continue
            if fd == proc.stdout.fileno():
                line = proc.stdout.readline()
                self.logger.debug('>> %s', line)
            elif fd == proc.stderr.fileno():
                line = proc.stderr.readline()
                self.logger.error('>> %s', line)
    for line in proc.stdout.readlines():
        self.logger.debug('>> %s', line)
    for line in proc.stderr.readlines():
        self.logger.error('>> %s', line)
    ret = proc.wait()
    self.logger.debug('Returned %d in %s seconds', ret, int(time.time() - start))
    if ret and (not allow_fail):
        self.logger.error("Unable to run '%s'", command_list)
        raise self.command_exception(error_msg)

def solve_output(self, **input_types):
    solved_outputs = self.outputs
    for (output_name, spec) in solved_outputs.items():
        if not spec.qiime_type.is_concrete():
            raise TypeError('Solved output %r must be a concrete type, not %r' % (output_name, spec.qiime_type))
    return solved_outputs

def solve_output(self, **input_types):
    solved_outputs = self.__class__(**input_types).outputs
    for (output_name, spec) in solved_outputs.items():
        if not spec.qiime_type.is_concrete():
            raise TypeError('Solved output %r must be a concrete type, not %r' % (output_name, spec.qiime_type))
    return solved_outputs

from xml.sax.saxutils import escape, quoteattr

def setAuthors(template, authors):
    text = ''
    for (name, href) in authors:
        anchor = '<a href="%s">%s</a>' % (quoteattr(href), escape(name))
        if (name, href) == authors[-1]:
            if len(authors) == 1:
                text = anchor
            else:
                text += 'and ' + anchor
        else:
            text += anchor + ','
    childNodes = microdom.parseString('<span>' + text + '</span>').childNodes
    for node in domhelpers.findElementsWithAttribute(template, 'class', 'authors'):
        node.childNodes.extend(childNodes)
    head = domhelpers.findNodesNamed(template, 'head')[0]
    authors = [microdom.parseString('<link rel="author" href="%s" title="%s"/>' % (quoteattr(href), escape(name))).childNodes[0] for (name, href) in authors]
    head.childNodes.extend(authors)

def dotedges(expr, atom=lambda x: not isinstance(x, Basic), pos=(), repeat=True):
    if atom(expr):
        return []
    else:
        (expr_str, arg_strs) = purestr(expr, with_args=True)
        if repeat:
            expr_str += '_%s' % str(pos)
            arg_strs = ['%s_%s' % (arg_str, str(pos + (i,))) for (i, arg_str) in enumerate(arg_strs)]
        return ['"%s" -> "%s";' % (expr_str, arg_str) for arg_str in arg_strs]

def on_window_keypress_event(self, widget, event, user_data=None):
    if check_keypress(event, ['Control', 'f']):
        self.search_box.grab_focus()
        return True
    if check_keypress(event, ['Control', 's']):
        self.activate_action_cb(None, 'save_launcher')
        return True
    return False

from typing import Optional

def lookup_class(kind: str, apiVersion: Optional[str]=None, default: Optional[object]=None) -> object:
    if kind in _ClassRegistry:
        return _ClassRegistry[kind]
    elif kind in _shortNameRegistry:
        className = _shortNameRegistry[kind]
    else:
        className = kind
    try:
        klass = load_class(className)
    except ImportError:
        klass = None
    if klass:
        register_class(className, klass)
    return klass

def good_friday_unless_christmas_nye_friday(dt):
    if isinstance(dt, pd.DataFrame) or isinstance(dt, pd.Series):
        return dt.apply(good_friday_unless_christmas_nye_friday)
    year = dt.year
    christmas_weekday = Christmas.observance(pd.Timestamp(year, 12, 25)).weekday()
    nyd_weekday = USNewYearsDay.observance(pd.Timestamp(year, 1, 1)).weekday()
    if christmas_weekday != 4 and nyd_weekday != 4:
        return GoodFriday._apply_rule(dt)
    else:
        return pd.NaT

def good_friday_unless_christmas_nye_friday(dt):
    if isinstance(dt, pd.Series):
        year = dt.dt.year
    else:
        year = dt.year
    christmas_weekday = Christmas.observance(pd.Timestamp(year, 12, 25)).weekday()
    nyd_weekday = USNewYearsDay.observance(pd.Timestamp(year, 1, 1)).weekday()
    if christmas_weekday != 4 and nyd_weekday != 4:
        return GoodFriday._apply_rule(dt)
    else:
        return pd.NaT

def __init__(self, options=None, register_classes=()):
    self.logger.debug('Creating %s arch', self.name)
    self.option_settings = {o: False for o in self.option_names}
    if options:
        assert isinstance(options, tuple)
        for option_name in options:
            assert option_name in self.option_names
            self.option_settings[option_name] = True
    self.register_classes = register_classes
    self.byte_sizes = {}
    self.byte_sizes['int'] = 4
    self.byte_sizes['ptr'] = 4
    self.byte_sizes['byte'] = 1
    self.byte_sizes['u8'] = 1
    self.FrameClass = Frame

