def set_doc_variables(item, job, params):
    change = item.change
    doc_subpath = ''
    if hasattr(change, 'ref'):
        tag = re.match('^refs/tags/(.*)', change.ref)
        if tag:
            doc_subpath = tag.group(1)
        else:
            doc_subpath = change.ref
    elif hasattr(change, 'refspec'):
        doc_subpath = change.branch
    if doc_subpath:
        params['DOC_SUBPATH'] = doc_subpath
    if 'ZUUL_PROJECT' in params:
        raw_project = params['ZUUL_PROJECT']
        if raw_project in doc_destination:
            raw_project = doc_destination[raw_project]
        elif raw_project.startswith('mediawiki/extensions/'):
            raw_project = raw_project.split('/')[-1]
        params['DOC_PROJECT'] = raw_project.replace('/', '-')

def getWeaponSystemData(fit):
    weaponSystems = []
    groups = {}
    defaultSpoolValue = 1
    spoolOptions = SpoolOptions(SpoolType.SCALE, defaultSpoolValue, False)
    for mod in fit.modules:
        spoolup = mod.getModifiedItemAttr('spoolup') if mod.getModifiedItemAttr('spoolup') is not None else defaultSpoolValue
        if mod.getDps(spoolOptions=spoolOptions).total > 0:
            keystr = str(mod.itemID) + '-' + str(mod.chargeID)
            if keystr in groups:
                groups[keystr][1] += 1
            else:
                groups[keystr] = [mod, 1]
    for wepGroup in groups.values():
        stats = wepGroup[0]
        n = wepGroup[1]
        tracking = 0
        maxVelocity = 0
        explosionDelay = 0
        damageReductionFactor = 0
        explosionRadius = 0
        explosionVelocity = 0
        aoeFieldRange = 0
        typeing = 'None'
        if stats.charge:
            name = stats.item.name + ', ' + stats.charge.name
        else:
            name = stats.item.name
        if stats.hardpoint == Hardpoint.TURRET:
            tracking = stats.getModifiedItemAttr('trackingSpeed')
            typeing = 'Turret'
        elif stats.hardpoint == Hardpoint.MISSILE or 'Bomb Launcher' in stats.item.name:
            maxVelocity = stats.getModifiedChargeAttr('maxVelocity')
            explosionDelay = stats.getModifiedChargeAttr('explosionDelay')
            damageReductionFactor = stats.getModifiedChargeAttr('aoeDamageReductionFactor')
            explosionRadius = stats.getModifiedChargeAttr('aoeCloudSize')
            explosionVelocity = stats.getModifiedChargeAttr('aoeVelocity')
            typeing = 'Missile'
        elif stats.hardpoint == Hardpoint.NONE:
            aoeFieldRange = stats.getModifiedItemAttr('empFieldRange')
            typeing = 'SmartBomb'
        if stats.item.group.name == 'Super Weapon' and stats.maxRange is None:
            maxRange = 300000
        else:
            maxRange = stats.maxRange
        statDict = {'dps': stats.getDps(spoolOptions=spoolOptions).total * n, 'capUse': stats.capUse * n, 'falloff': stats.falloff, 'type': typeing, 'name': name, 'optimal': maxRange, 'numCharges': stats.numCharges, 'numShots': stats.numShots, 'reloadTime': stats.reloadTime, 'cycleTime': stats.cycleTime, 'volley': stats.getVolley(spoolOptions=spoolOptions).total * n, 'tracking': tracking, 'maxVelocity': maxVelocity, 'explosionDelay': explosionDelay, 'damageReductionFactor': damageReductionFactor, 'explosionRadius': explosionRadius, 'explosionVelocity': explosionVelocity, 'aoeFieldRange': aoeFieldRange, 'damageMultiplierBonusMax': stats.getModifiedItemAttr('damageMultiplierBonusMax'), 'damageMultiplierBonusPerCycle': stats.getModifiedItemAttr('damageMultiplierBonusPerCycle')}
        weaponSystems.append(statDict)
    for drone in fit.drones:
        if drone.getDps().total > 0 and drone.amountActive > 0:
            droneAttr = drone.getModifiedItemAttr
            newTracking = droneAttr('trackingSpeed') / (droneAttr('optimalSigRadius') / 40000)
            statDict = {'dps': drone.getDps().total, 'cycleTime': drone.cycleTime, 'type': 'Drone', 'optimal': drone.maxRange, 'name': drone.item.name, 'falloff': drone.falloff, 'maxSpeed': droneAttr('maxVelocity'), 'tracking': newTracking, 'volley': drone.getVolley().total}
            weaponSystems.append(statDict)
    for fighter in fit.fighters:
        if fighter.getDps().total > 0 and fighter.amountActive > 0:
            fighterAttr = fighter.getModifiedItemAttr
            abilities = []
            if 'fighterAbilityAttackMissileDamageEM' in fighter.item.attributes.keys():
                baseRef = 'fighterAbilityAttackMissile'
                ability = EfsPort.getFighterAbilityData(fighterAttr, fighter, baseRef)
                abilities.append(ability)
            if 'fighterAbilityMissilesDamageEM' in fighter.item.attributes.keys():
                baseRef = 'fighterAbilityMissiles'
                ability = EfsPort.getFighterAbilityData(fighterAttr, fighter, baseRef)
                abilities.append(ability)
            statDict = {'dps': fighter.getDps().total, 'type': 'Fighter', 'name': fighter.item.name, 'maxSpeed': fighterAttr('maxVelocity'), 'abilities': abilities, 'ehp': fighterAttr('shieldCapacity') / 0.8875 * fighter.amountActive, 'volley': fighter.getVolley().total, 'signatureRadius': fighterAttr('signatureRadius')}
            weaponSystems.append(statDict)
    return weaponSystems

def RunStateMethod(self, method_name: str, request: Optional[rdf_flow_runner.RequestState]=None, responses: Optional[Sequence[rdf_flow_objects.FlowMessage]]=None) -> None:
    client_id = self.rdf_flow.client_id
    deadline = self.rdf_flow.processing_deadline
    if deadline and rdfvalue.RDFDatetime.Now() > deadline:
        raise FlowError('Processing time for flow %s on %s expired.' % (self.rdf_flow.flow_id, self.rdf_flow.client_id))
    self.rdf_flow.current_state = method_name
    if request and responses:
        logging.debug('Running %s for flow %s on %s, %d responses.', method_name, self.rdf_flow.flow_id, client_id, len(responses))
    else:
        logging.debug('Running %s for flow %s on %s', method_name, self.rdf_flow.flow_id, client_id)
    try:
        try:
            method = getattr(self, method_name)
        except AttributeError:
            raise ValueError('Flow %s has no state method %s' % (self.__class__.__name__, method_name))
        responses = flow_responses.Responses.FromResponses(request=request, responses=responses)
        if responses.status is not None:
            self.SaveResourceUsage(responses.status)
        GRR_WORKER_STATES_RUN.Increment()
        if method_name == 'Start':
            FLOW_STARTS.Increment(fields=[self.rdf_flow.flow_class_name])
            method()
        else:
            method(responses)
        if self.replies_to_process:
            if self.rdf_flow.parent_hunt_id and (not self.rdf_flow.parent_flow_id):
                self._ProcessRepliesWithHuntOutputPlugins(self.replies_to_process)
            else:
                self._ProcessRepliesWithFlowOutputPlugins(self.replies_to_process)
            self.replies_to_process = []
    except flow.FlowResourcesExceededError as e:
        FLOW_ERRORS.Increment(fields=[self.rdf_flow.flow_class_name])
        logging.info('Flow %s on %s exceeded resource limits: %s.', self.rdf_flow.flow_id, client_id, str(e))
        self.Error(error_message=str(e))
    except Exception as e:
        msg = str(e)
        FLOW_ERRORS.Increment(fields=[self.rdf_flow.flow_class_name])
        self.Error(error_message=msg, backtrace=traceback.format_exc())

def spawn_locusts(self, spawn_count=None, stop_timeout=None, wait=False):
    if spawn_count is None:
        spawn_count = self.num_clients
    if self.num_requests is not None:
        RequestStats.global_max_requests = self.num_requests
    bucket = self.weight_locusts(spawn_count, stop_timeout)
    spawn_count = len(bucket)
    if self.state == STATE_INIT or self.state == STATE_STOPPED:
        self.state = STATE_HATCHING
        self.num_clients = spawn_count
    else:
        self.num_clients += spawn_count
    logger.info('Hatching and swarming %i clients at the rate %g clients/s...' % (spawn_count, self.hatch_rate))
    occurence_count = dict([(l.__name__, 0) for l in self.locust_classes])

    def hatch():
        sleep_time = 1.0 / self.hatch_rate
        while True:
            if not bucket:
                logger.info('All locusts hatched: %s' % ', '.join(['%s: %d' % (name, count) for (name, count) in occurence_count.items()]))
                events.hatch_complete.fire(self.num_clients)
                return
            locust = bucket.pop(random.randint(0, len(bucket) - 1))
            occurence_count[locust.__name__] += 1

            def start_locust(_):
                try:
                    locust().run()
                except GreenletExit:
                    pass
            new_locust = self.locusts.spawn(start_locust, locust)
            if len(self.locusts) % 10 == 0:
                logger.debug('%i locusts hatched' % len(self.locusts))
            gevent.sleep(sleep_time)
    hatch()
    if wait:
        self.locusts.join()
        logger.info('All locusts dead\n')
        self.environment.events.locusts_stopped.fire(self.request_stats)

def __init__(self, dn: str, modifications: types.NormalizedAttributes) -> None:
    super().__init__(record_dn=dn)
    self.modifications = modifications

def create(entity_type=None, entity_id=None):
    if not (entity_id or entity_type):
        for allowed_type in ENTITY_TYPES:
            if (mbid := request.args.get(allowed_type)):
                entity_type = allowed_type
                entity_id = mbid
                break
        if entity_type:
            return redirect(url_for('.create', entity_type=entity_type, entity_id=entity_id))
        flash.info(gettext('Please choose an entity to review.'))
        return redirect(url_for('search.selector', next=url_for('.create')))
    if entity_type not in ENTITY_TYPES:
        raise BadRequest("You can't write reviews about this type of entity.")
    if current_user.is_blocked:
        flash.error(gettext('You are not allowed to write new reviews because your account has been blocked by a moderator.'))
        return redirect(url_for('user.reviews', user_id=current_user.id))
    (reviews, count) = db_review.list_reviews(user_id=current_user.id, entity_id=entity_id, inc_drafts=True, inc_hidden=True)
    review = reviews[0] if count != 0 else None
    if review:
        if review['is_draft']:
            return redirect(url_for('review.edit', id=review['id']))
        elif review['is_hidden']:
            return redirect(url_for('review.entity', id=review['id']))
        else:
            flash.error(gettext('You have already published a review for this entity'))
            return redirect(url_for('review.entity', id=review['id']))
    if current_user.is_review_limit_exceeded:
        flash.error(gettext('You have exceeded your limit of reviews per day.'))
        return redirect(url_for('user.reviews', user_id=current_user.id))
    form = ReviewCreateForm(default_license_id=current_user.license_choice, default_language=get_locale())
    if form.validate_on_submit():
        is_draft = form.state.data == 'draft'
        if form.text.data == '':
            form.text.data = None
        review = db_review.create(user_id=current_user.id, entity_id=entity_id, entity_type=entity_type, text=form.text.data, rating=form.rating.data, license_id=form.license_choice.data, language=form.language.data, is_draft=is_draft)
        if form.remember_license.data:
            db_users.update(current_user.id, user_new_info={'license_choice': form.license_choice.data})
        if is_draft:
            flash.success(gettext('Review has been saved!'))
        else:
            flash.success(gettext('Review has been published!'))
        return redirect(url_for('.entity', id=review['id']))
    try:
        _entity = get_entity_by_id(entity_id, entity_type)
        data = {'form': form, 'entity_type': entity_type, 'entity': _entity}
    except NoDataFoundException:
        raise NotFound(gettext("Sorry, we couldn't find a %s with that MusicBrainz ID." % entity_type))
    data['entity_title'] = get_entity_title(_entity)
    if entity_type == 'release_group':
        data['spotify_mappings'] = mbspotify.mappings(entity_id)
        data['soundcloud_url'] = soundcloud.get_url(entity_id)
    if not form.errors:
        flash.info(gettext('Please provide some text or a rating for this review.'))
    return render_template('review/modify/write.html', **data)

